第一个网络通讯程序.qiwnttifdnzq{zoom:67%;}

客户&#x2F;服务器
网络通讯是指两台计算机中的程序进行传输数据的过程
客户程序（端）：指主动发起通讯的程序
服务程序（端&#x2F;器）：指被动的等待，然后为向它发起通讯的客户端提供服务
客户端必须提前知道服务端的 IP 地址和通讯端口
服务端不需要知道客户端的 IP 地址

/* * 程序名：demo1.cpp，此程序用于演示 socket 的客户端*/#include &lt;iostream&gt;#include &lt;cstdio&gt;#include &lt;cstring&gt;#include &lt;cstdlib&gt;#include &lt;unistd.h&gt;#include &lt;netdb.h&gt;#include &lt;sys/types.h&gt;#include &lt;sys/socket.h&gt;#include &lt;arpa/inet.h&gt;using namespace std;int main(int argc, char* argv[])&#123;    if(argc != 3)    &#123;        cout &lt;&lt; &quot;Using: ./demo1 服务端的 IP 服务端的端口 \nExample: ./demo1 192.168.112.131 5005\n\n&quot;;        return -1;    &#125;        // 第1步：创建客户端的 socket    int sockfd = socket(AF_INET, SOCK_STREAM, 0);    if(sockfd == -1)    &#123;        perror(&quot;socket&quot;);        return -1;    &#125;        // 第2步：向服务器发起连接请求    struct hostent* h;	// 用于存放服务器 IP 的数据结构    if((h = gethostbyname(argv[1])) == 0)	// 指定服务端的 ip 地址    &#123;        cout &lt;&lt; &quot;gethostbyname failed.\n&quot; &lt;&lt; endl;        close(sockfd);        return -1;    &#125;    struct sockaddr_in servaddr;    memset(&amp;servaddr, 0, sizeof(servaddr));    servaddr.sin_family = AF_INET;    servaddr.sin_port = htons(atoi(argv[2]));	// 指定服务端的通信端口    memcpy(&amp;servaddr.sin_addr, h-&gt;h_addr, h-&gt;h_length);    if(connect(sockfd, (struct sockaddr*)&amp;servaddr, sizeof(servaddr)) != 0)	// 向服务端发起连接请求    &#123;        perror(&quot;connect&quot;);        close(sockfd);        return -1;    &#125;        // 第3步：与服务端通信，发送一个请求报文后等待回复，然后再发下一个请求报文    char buffer[1024];    for(int ii=0; ii &lt; 3; ii++)	// 循环3次，将与服务端进行三次通讯    &#123;        int iret;        memset(buffer, 0, sizeof(buffer));        sprintf(buffer, &quot;这是第 %d 个报文，编号 %03d&quot;, ii + 1, ii + 1);	// 生成请求报文内容        // 向服务端发送请求报文，在网络传输数据的过程中，可以使用文件的 I/O 函数        if((iret=write(sockfd, buffer, strlen(buffer))) &lt;= 0)        // if((iret=send(sockfd, buffer, strlen(buffer), 0)) &lt;= 0)        &#123;            perror(&quot;send&quot;);            break;        &#125;        cout &lt;&lt; &quot;发送：&quot; &lt;&lt; buffer &lt;&lt; endl;                memset(buffer, 0, sizeof(buffer));        // 接收服务端的回应报文，如果服务端没有发送回应报文，recv() 函数将阻塞等待，在网络传输数据的过程中，可以使用文件的 I/O 函数        if((iret=read(sockfd, buffer, sizeof(buffer))) &lt;= 0)        //if((iret=recv(sockfd, buffer, sizeof(buffer), 0)) &lt;= 0)        &#123;            cout &lt;&lt; &quot;iret=&quot; &lt;&lt; iret &lt;&lt; endl;            break;        &#125;        cout &lt;&lt; &quot;接收：&quot; &lt;&lt; buffer &lt;&lt; endl;                sleep(1);    &#125;        // 第4步：关闭 socket，释放资源    close(sockfd);&#125;

/* * 程序名：demo2.cpp，此程序用于演示 socket 通信的服务端 */#include &lt;iostream&gt;#include &lt;cstdio&gt;#include &lt;cstring&gt;#include &lt;cstdlib&gt;#include &lt;unistd.h&gt;#include &lt;netdb.h&gt;#include &lt;sys/types.h&gt;#include &lt;sys/socket.h&gt;#include &lt;arpa/inet.h&gt;using namespace std;int main(int argc, char* argv[])&#123;    if(argc != 2)    &#123;        cout &lt;&lt; &quot;Using: ./demo2 通讯端口 \nExample: ./demo2 5005\n\n&quot;;        cout &lt;&lt; &quot;注意：运行服务端程序的 Linux 系统的防火墙必须要开通5005端口\n&quot;;        cout &lt;&lt; &quot;	如果是云服务器，还要开通云平台的访问策略\n\n&quot;;    &#125;        // 第1步：创建服务端的 socket    int listenfd = socket(AF_INET, SOCK_STREAM, 0);    if(listenfd == -1)    &#123;        perror(&quot;socket&quot;);        return -1;    &#125;        // 第2步：把服务端用于通信的 IP 和端口绑定到 socket 上    struct sockaddr_in servaddr;	// 用于存放服务端 IP 和端口的数据结构    memset(&amp;servaddr, 0, sizeof(servaddr));    servaddr.sin_family = AF_INET;		// 指定协议    servaddr.sin_addr.s_addr = htonl(INADDR_ANY);	// 服务端任意网卡的 IP 都可以用于通讯    servaddr.sin_port = htons(atoi(argv[1]));	// 指定通信端口，普通用户只能用1024以上的端口    // 绑定服务端的 IP 和端口    if(bind(listenfd, (struct sockaddr*)&amp;servaddr, sizeof(servaddr)) != 0)    &#123;        perror(&quot;bind&quot;);        close(listenfd);        return -1;    &#125;        // 第3步：把 socket 设置为可连接（监听）的状态    if(listen(listenfd, 5) != 0)    &#123;        perror(&quot;listen&quot;);        close(listenfd);        return -1;    &#125;        // 第4步：受理客户端的连接请求，如果没有客户端连上来，accept() 函数将阻塞等待    int clientfd = accept(listenfd, 0, 0);    if(clientfd == -1)    &#123;        perror(&quot;accept&quot;);        close(listenfd);        return -1;    &#125;        cout &lt;&lt; &quot;客户端已连接\n&quot;;        // 第5步：与客户端通信，接收客户端发过来的报文后，回复ok    char buffer[1024];    while(true)    &#123;        int iret;        memset(buffer, 0, sizeof(buffer));        // 接收客户端的请求报文，如果客户端没有发送请求报文，recv() 函数将阻塞等待        // 如果客户端已断开连接，recv() 函数将返回0        if((iret = recv(clientfd, buffer, sizeof(buffer), 0)) &lt;= 0)        &#123;            cout &lt;&lt; &quot;iret=&quot; &lt;&lt; iret &lt;&lt; endl;            break;        &#125;        cout &lt;&lt; &quot;接收：&quot; &lt;&lt; buffer &lt;&lt; endl;                strcpy(buffer, &quot;ok&quot;);	// 生成回应报文内容        // 向客户端发送回应报文        if((iret=send(clientfd, buffer, strlen(buffer), 0)) &lt;= 0)        &#123;            perror(&quot;send&quot;);            break;        &#125;        cout &lt;&lt; &quot;发送：&quot; &lt;&lt; buffer &lt;&lt; endl;    &#125;        // 第6步：关闭 socket，释放资源    close(listenfd);    close(clientfd);&#125;

