客户端和服务端程序可以运行在不同的虚拟机上，也可以运行在同一个虚拟机上，网络通信的客户端和服务端是逻辑的概念，与物理计算机和操作系统没有关系
基于 Linux 的文件操作
对 Linux 来说，socket 操作与文件操作没有区别
在网络传输数据的过程中，可以使用文件的 I&#x2F;O 函数
文件描述符是 Linux 分配给文件或 socket 的整数

// demo3.cpp，本程序演示了 Linux 底层文件的操作——创建文件并写入数据#include &lt;stdio.h&gt;#include &lt;stdlib.h&gt;#include &lt;string.h&gt;#include &lt;fcntl.h&gt;#include &lt;unistd.h&gt;int main()&#123;    int fd;		// 定义一个文件描述符/文件句柄        fd = open(&quot;data.txt&quot;, O_CREAT|O_RDWR|O_TRUNC);	// 打开文件	O_CREAT 创建文件 O_RDWR 可读可写 O_TRUNC 是否截断文件    if(fd == -1)    &#123;        perror(&quot;open(data.txt)&quot;);        return -1;    &#125;        printf(&quot;文件描述符 fd=%d\n&quot;, fd);        char buffer[1024];    strcpy(buffer, &quot;我是渺如星辰\n&quot;);        if(write(fd, buffer, strlen(buffer)) == -1)		// 把数据写入文件    &#123;        perror(&quot;write()&quot;);        return -1;    &#125;        close(fd);	// 关闭文件&#125;

