typedef unsigned int in_addr_t;			// 32位大端序的 IP 地址// 把字符串格式的 IP 转换成大端序的 IP，转换后的 IP 值赋给 sockaddr_in.in_addr.s_addr，只能用 IP，不能用域名和主机名in_addr_t inet_addr(const char *cp);// 把字符串格式的 IP 转换成大端序的 IP，转换后的 IP 填充到 sockaddr_in.in_addr 成员int inet_aton(const char *cp, struct in_addr *inp);// 把大端序 IP 转换成字符串格式的 IP，用于在服务端程序中解析客户端的 IP 地址char *inet_ntoa(struct in_addr in);

封装 socket
网络编程涉及到多个数据结构和函数，使用起来不方便
把客户端程序用到的数据结构和函数封装成 ctcpclient 类
把服务端程序用到的数据结构和函数封装成 ctcpserver 类

/* * 程序名：demo5.cpp，此程序用于演示封装 socket 通讯的客户端*/#include &lt;iostream&gt;#include &lt;cstdio&gt;#include &lt;cstring&gt;#include &lt;cstdlib&gt;#include &lt;unistd.h&gt;#include &lt;netdb.h&gt;#include &lt;sys/types.h&gt;#include &lt;sys/socket.h&gt;#include &lt;arpa/inet.h&gt;using namespace std;class ctcpclient			// TCP 通讯的客户端类&#123;private:    int m_clientfd;			// 客户端的 socket，-1表示未连接或连接已断开；&gt;=0表示有效的 socket    string m_ip;			// 服务端的 IP /域名    unsigned short m_port;	 // 通讯端口    public:    ctcpclient() : m_clientfd(-1) &#123;&#125;        // 向服务端发起连接请求，成功返回 true，失败返回 false    bool connect(const string &amp;in_ip, const unsigned short in_port)    &#123;        if(m_clientfd != -1)	return false;	// 如果 socket 已连接，直接返回失败                // 把服务端的 IP 和端口保存到成员变量中        m_ip = in_ip;        m_port = in_port;                // 第1步：创建客户端的 socket        if((m_clientfd = socket(AF_INET, SOCK_STREAM, 0)) == -1)        &#123;            return false;        &#125;        // 第2步：向服务器发起连接请求        struct sockaddr_in servaddr;				// 用于存放协议、端口和 IP 地址的结构体        memset(&amp;servaddr, 0, sizeof(servaddr));        servaddr.sin_family = AF_INET;				// 1）协议族，固定填 AF_INET        servaddr.sin_port = htons(m_port);	// 2）指定服务端的通信端口                struct hostent* h;	// 用于存放服务器 IP 地址（大端序）的结构体的指针        if((h = gethostbyname(m_ip.c_str())) == nullptr)	// 把域名/主机名/字符串格式的 IP 转换成结构体        &#123;            ::close(m_clientfd);	// 全局 close 库函数            m_clientfd = -1;            return false;        &#125;        memcpy(&amp;servaddr.sin_addr, h-&gt;h_addr, h-&gt;h_length);		// 3）指定服务端的 IP（大端序）                // 向服务端发起连接请求        if(::connect(m_clientfd, (struct sockaddr *)&amp;servaddr, sizeof(servaddr)) == -1)	// 全局 connect 库函数        &#123;            ::close(m_clientfd);	// 全局 close 库函数            m_clientfd = -1;            return false;        &#125;                return true;    &#125;        // 向服务端发送报文，成功返回 true，失败返回 false    bool send(const string &amp;buffer)		// buffer 不要用 const char *    &#123;	    if(m_clientfd == -1)	return false;	// 如果 socket 的状态是未连接，直接返回失败                if((::send(m_clientfd, buffer.data(), buffer.size(), 0)) &lt;= 0) return false;	// 全局 send 库函数                return true;    &#125;               // 接收服务端的报文，成功返回 true，失败返回 false    // buffer-存放接收到的报文的内容，maxlen-本次接收报文的最大长度    bool recv(string &amp;buffer, const size_t maxlen)    &#123;	// 如果直接操作 string 对象的内存，必须保证：1 不能越界	2 操作后手动设置数据的大小        buffer.clear();			// 清空容器        buffer.resize(maxlen);	// 设置容器的大小为 maxlen        int readn = ::recv(m_clientfd, &amp;buffer[0], buffer.size(), 0);	// 直接操作 buffer 的内存，全局 recv 库函数        if(readn &lt;= 0)        &#123;            buffer.clear();            return false;        &#125;        buffer.resize(readn);	// 重置 buffer 的实际大小                return true;    &#125;               // 断开与服务端的连接    bool close()    &#123;        if(m_clientfd == -1) return false;	// 如果 socket 的状态是未连接，直接返回失败                ::close(m_clientfd);        m_clientfd = -1;        return true;    &#125;    ~ctcpclient()     &#123;    	close();               &#125;&#125;;int main(int argc, char* argv[])&#123;    if(argc != 3)    &#123;        cout &lt;&lt; &quot;Using: ./demo5 服务端的 IP 服务端的端口 \nExample: ./demo5 192.168.112.131 5005\n\n&quot;;        return -1;    &#125;        ctcpclient tcpclient;    if(tcpclient.connect(argv[1], atoi(argv[2])) == false)	// 向服务端发起连接请求    &#123;        perror(&quot;connect()&quot;);        return -1;    &#125;        // 第3步：与服务端通信，客户发送一个请求报文后等待服务端的回复，收到回复后，再发下一个请求报文    string buffer;    for(int ii = 0; ii &lt; 3; ii++)	// 循环3次，将与服务端进行三次通讯    &#123;        buffer = &quot;这是第&quot; + to_string(ii + 1) + &quot;个报文，编号&quot; + to_string(ii + 1); // 生成请求报文内容        // 向服务端发送请求报文        if(tcpclient.send(buffer) == false)        &#123;            perror(&quot;send&quot;);            break;        &#125;        cout &lt;&lt; &quot;发送：&quot; &lt;&lt; buffer &lt;&lt; endl;                // 接收服务端的回应报文，如果服务端没有发送回应报文，recv() 函数将阻塞等待        if(tcpclient.recv(buffer, 1024) == false)        &#123;            perror(&quot;recv()&quot;);            break;        &#125;        cout &lt;&lt; &quot;接收：&quot; &lt;&lt; buffer &lt;&lt; endl;                sleep(1);    &#125;&#125;

/* * 程序名：demo6.cpp，此程序用于演示封装 socket 通讯的服务端*/#include &lt;iostream&gt;#include &lt;cstdio&gt;#include &lt;cstring&gt;#include &lt;cstdlib&gt;#include &lt;unistd.h&gt;#include &lt;netdb.h&gt;#include &lt;sys/types.h&gt;#include &lt;sys/socket.h&gt;#include &lt;arpa/inet.h&gt;using namespace std;class ctcpserver		// TCP通讯的服务端类&#123;private:    int		m_listenfd;		// 监听的 socket, -1表示未初始化    int		m_clientfd;		// 客户端连上来的 socket，-1表示客户端未连接    string	m_clientip;		// 客户端字符串格式的 IP    unsigned short m_port;	// 服务端用于通讯的端口public:    ctcpserver() : m_listenfd(-1), m_clientfd(-1) &#123;&#125;        // 初始化服务端用于监听的 socket    bool initserver(const unsigned short in_port)    &#123;        // 第1步：创建服务端的 socket        if((m_listenfd = socket(AF_INET, SOCK_STREAM, 0)) == -1) return false;                m_port = in_port;        // 第2步：把服务端用于通信的 IP 和端口绑定到 socket 上        struct sockaddr_in servaddr;	// 用于存放协议、端口和 IP 地址的结构体        memset(&amp;servaddr, 0, sizeof(servaddr));        servaddr.sin_family = AF_INET;		// 1 协议族，固定填 AF_INET        servaddr.sin_port = htons(m_port);	// 2 指定服务端的通信端口        servaddr.sin_addr.s_addr = htonl(INADDR_ANY);	// 3 如果操纵系统有多个 IP，全部的 IP 都可以用于通讯                // 绑定服务端的 IP 和端口（为 socket 分配 IP 和端口）        if(bind(m_listenfd, (struct sockaddr*)&amp;servaddr, sizeof(servaddr)) == -1)        &#123;            close(m_listenfd);            m_listenfd = -1;            return false;        &#125;        // 第3步：把 socket 设置为可连接（监听）的状态        if(listen(m_listenfd, 5) == -1)        &#123;            close(m_listenfd);            m_listenfd = -1;            return false;        &#125;                return true;    &#125;        // 受理客户端的连接（从已连接的客户端中取出一个客户端），如果没有已连接的客户端，accept() 函数将阻塞等待    bool accept()    &#123;        struct sockaddr_in caddr;			// 客户端的地址信息        socklen_t addrlen = sizeof(caddr);	 // struct sockaddr_in 的大小        if((m_clientfd = ::accept(m_listenfd, 0, 0)) == -1) return false;	// 全局 accept 库函数                m_clientip = inet_ntoa(caddr.sin_addr);		// 把客户端的地址从大端序转换成字符串                return true;    &#125;        // 获取客户端的 IP（字符串格式）    const string&amp; clientip() const    &#123;        return m_clientip;    &#125;        // 向对端发送报文，成功返回 true，失败返回 false    bool send(const string&amp; buffer)    &#123;        if(m_clientfd == -1) return false;                if((::send(m_clientfd, buffer.data(), buffer.size(), 0)) &lt;= 0) return false;	// 全局 send 库函数                return true;    &#125;        // 接收对端的报文，成功返回 true，失败返回 false    // buffer-存放接收到的报文的内容，maxlen-本次接收报文的最大长度    bool recv(string&amp; buffer, const size_t maxlen)    &#123;        buffer.clear();			// 清空容器        buffer.resize(maxlen);	// 设置容器的大小为 maxlen        int readn = ::recv(m_clientfd, &amp;buffer[0], buffer.size(), 0);	// 直接操作 buffer 的内存，全局 recv 库函数        if(readn &lt;= 0)        &#123;            buffer.clear();            return false;        &#125;        buffer.resize(readn);	// 重置 buffer 的实际大小                return true;    &#125;        // 关闭监听的 socket    bool closelisten()    &#123;        if(m_listenfd == -1)	return false;                close(m_listenfd);        m_listenfd = -1;        return true;    &#125;        // 关闭客户端连上来的 socket    bool closeclient()    &#123;        if(m_clientfd == -1) return false;                close(m_clientfd);        m_clientfd = -1;        return true;    &#125;        ~ctcpserver()    &#123;        closelisten();        closeclient();    &#125;&#125;;int main(int argc, char* argv[])&#123;    if(argc != 2)    &#123;        cout &lt;&lt; &quot;Using: ./demo2 通讯端口 \nExample: ./demo2 5005\n\n&quot;;        cout &lt;&lt; &quot;注意：运行服务端程序的 Linux 系统的防火墙必须要开通5005端口\n&quot;;        cout &lt;&lt; &quot;	如果是云服务器，还要开通云平台的访问策略\n\n&quot;;        return -1;    &#125;        ctcpserver tcpserver;    if(tcpserver.initserver(atoi(argv[1])) == false)	// 初始化服务端用于监听的 socket    &#123;        perror(&quot;initserver()&quot;);        return -1;    &#125;        // 受理客户端的连接（从已连接的客户端中取出一个客户端），如果没有已连接的客户端，accept() 函数将阻塞等待    if(tcpserver.accept() == false)    &#123;        perror(&quot;accept()&quot;);        return -1;    &#125;    cout &lt;&lt; &quot;客户端已连接(&quot; &lt;&lt;tcpserver.clientip() &lt;&lt; &quot;)\n&quot;;        string buffer;    while(true)    &#123;        // 接收对端的报文，如果对端没有发送报文，recv() 函数将阻塞等待        if(tcpserver.recv(buffer, 1024) == false)        &#123;            perror(&quot;recv()&quot;);            break;        &#125;        cout &lt;&lt; &quot;接收：&quot; &lt;&lt; buffer &lt;&lt; endl;                buffer = &quot;ok&quot;;	// 生成回应报文内容        // 向对端发送报文        if(tcpserver.send(buffer) == false)        &#123;            perror(&quot;send&quot;);            break;        &#125;        cout &lt;&lt; &quot;发送：&quot; &lt;&lt; buffer &lt;&lt; endl;    &#125;&#125;

多进程的服务端在多进程的服务程序中，如果子进程收到退出信号，子进程自行退出，如果父进程收到退出信号，则应该先向全部的子进程发送退出信号，然后自己再退出父进程只受理客户端的连接，不与客户端通讯子进程负责与客户端通讯，不受理客户端的连接fork 之后，父进程不需要 tcpserver.m_clientfd，子进程不需要 tcpserver.m_listenfd
/* * 程序名：demo7.cpp，此程序用于演示多进程的 socket 服务端*/#include &lt;iostream&gt;#include &lt;cstdio&gt;#include &lt;cstring&gt;#include &lt;cstdlib&gt;#include &lt;unistd.h&gt;#include &lt;signal.h&gt;#include &lt;netdb.h&gt;#include &lt;sys/types.h&gt;#include &lt;sys/socket.h&gt;#include &lt;arpa/inet.h&gt;using namespace std;class ctcpserver		// TCP通讯的服务端类&#123;private:    int		m_listenfd;		// 监听的 socket, -1表示未初始化    int		m_clientfd;		// 客户端连上来的 socket，-1表示客户端未连接    string	m_clientip;		// 客户端的 IP    unsigned short m_port;	// 服务端用于通讯的端口public:    ctcpserver() : m_listenfd(-1), m_clientfd(-1) &#123;&#125;        // 初始化服务端用于监听的 socket    bool initserver(const unsigned short in_port)    &#123;        // 第1步：创建服务端的 socket        if((m_listenfd = socket(AF_INET, SOCK_STREAM, 0)) == -1) return false;                m_port = in_port;        // 第2步：把服务端用于通信的 IP 和端口绑定到 socket 上        struct sockaddr_in servaddr;	// 用于存放协议、端口和 IP 地址的结构体        memset(&amp;servaddr, 0, sizeof(servaddr));        servaddr.sin_family = AF_INET;		// 1 协议族，固定填 AF_INET        servaddr.sin_port = htons(m_port);	// 2 指定服务端的通信端口        servaddr.sin_addr.s_addr = htonl(INADDR_ANY);	// 3 如果操纵系统有多个 IP，全部的 IP 都可以用于通讯                // 绑定服务端的 IP 和端口（为 socket 分配 IP 和端口）        if(bind(m_listenfd, (struct sockaddr*)&amp;servaddr, sizeof(servaddr)) == -1)        &#123;            close(m_listenfd);            m_listenfd = -1;            return false;        &#125;        // 第3步：把 socket 设置为可连接（监听）的状态        if(listen(m_listenfd, 5) == -1)        &#123;            close(m_listenfd);            m_listenfd = -1;            return false;        &#125;                return true;    &#125;        // 受理客户端的连接（从已连接的客户端中取出一个客户端），如果没有已连接的客户端，accept() 函数将阻塞等待    bool accept()    &#123;        struct sockaddr_in caddr;			// 客户端的地址信息        socklen_t addrlen = sizeof(caddr);	 // struct sockaddr_in 的大小        if((m_clientfd = ::accept(m_listenfd, 0, 0)) == -1) return false;	// 全局 accept 库函数                m_clientip = inet_ntoa(caddr.sin_addr);		// 客户端的地址从大端序转换成字符串                return true;    &#125;        // 获取客户端的 IP（字符串格式）    const string&amp; clientip() const    &#123;        return m_clientip;    &#125;        // 向对端发送报文，成功返回 true，失败返回 false    bool send(const string&amp; buffer)    &#123;        if(m_clientfd == -1) return false;                if((::send(m_clientfd, buffer.data(), buffer.size(), 0)) &lt;= 0) return false;	// 全局 send 库函数                return true;    &#125;        // 接收对端的报文，成功返回 true，失败返回 false    // buffer-存放接收到的报文的内容，maxlen-本次接收报文的最大长度    bool recv(string&amp; buffer, const size_t maxlen)    &#123;        buffer.clear();			// 清空容器        buffer.resize(maxlen);	// 设置容器的大小为 maxlen        int readn = ::recv(m_clientfd, &amp;buffer[0], buffer.size(), 0);	// 直接操作 buffer 的内存，全局 recv 库函数        if(readn &lt;= 0)        &#123;            buffer.clear();            return false;        &#125;        buffer.resize(readn);	// 重置 buffer 的实际大小                return true;    &#125;        // 关闭监听的 socket    bool closelisten()    &#123;        if(m_listenfd == -1)	return false;                close(m_listenfd);        m_listenfd = -1;        return true;    &#125;        // 关闭客户端连上来的 socket    bool closeclient()    &#123;        if(m_clientfd == -1) return false;                close(m_clientfd);        m_clientfd = -1;        return true;    &#125;        ~ctcpserver()    &#123;        closelisten();        closeclient();    &#125;&#125;;ctcpserver tcpserver;void FathEXIT(int sig);		// 父进程的信号处理函数void ChldEXIT(int sig);		// 子进程的信号处理函数int main(int argc, char* argv[])&#123;    if(argc != 2)    &#123;        cout &lt;&lt; &quot;Using: ./demo7 通讯端口 \nExample: ./demo7 5005\n\n&quot;;        cout &lt;&lt; &quot;注意：运行服务端程序的 Linux 系统的防火墙必须要开通5005端口\n&quot;;        cout &lt;&lt; &quot;	如果是云服务器，还要开通云平台的访问策略\n\n&quot;;        return -1;    &#125;        // 忽略全部的信号，不希望被打扰，顺便解决了僵尸进程的问题    for(int ii = 1; ii &lt;= 64; ii++)	signal(ii, SIG_IGN);        // 设置信号，在 shell 状态下可用 &quot;kill 进程号&quot; 或 &quot;Ctrl+c&quot; 正常终止进程    // 但请不要用 &quot;kill -9 +进程号&quot; 强行终止    signal(SIGTERM, FathEXIT);    signal(SIGINT, FathEXIT);	// SIGTERM 15 SIGINT 2        if(tcpserver.initserver(atoi(argv[1])) == false)	// 初始化服务端用于监听的 socket    &#123;        perror(&quot;initserver()&quot;);        return -1;    &#125;        while(true)    &#123;        // 受理客户端的连接（从已连接的客户端中取出一个客户端），如果没有已连接的客户端，accept() 函数将阻塞等待        if(tcpserver.accept() == false)        &#123;            perror(&quot;accept()&quot;);            return -1;        &#125;                // 每受理一个客户端连接，就 fork 一个子进程，让子进程负责与这个客户端进行通讯，父进程继续受理客户端的连接        int pid = fork();        if(pid == -1)	// 系统资源不足        &#123;            perror(&quot;fork()&quot;);            return -1;        &#125;        if(pid &gt; 0)		// 父进程        &#123;            tcpserver.closeclient();	// 父进程关闭客户端连接的 socket            continue;				// 父进程返回到循环开始的位置，继续受理客户端的连接        &#125;                tcpserver.closelisten();		// 子进程关闭监听的 socket                // 子进程需要重新设置信号        signal(SIGTERM, ChldEXIT);		// 子进程的退出函数与父进程不一样        signal(SIGINT, SIG_IGN);		// 子进程不需要捕获 SIGINT 信号                // 子进程负责与客户端进行通讯        cout &lt;&lt; &quot;客户端已连接(&quot; &lt;&lt;tcpserver.clientip() &lt;&lt; &quot;)\n&quot;;        string buffer;        while(true)        &#123;            // 接收对端的报文，如果对端没有发送报文，recv() 函数将阻塞等待            if(tcpserver.recv(buffer, 1024) == false)            &#123;                perror(&quot;recv()&quot;);                break;            &#125;            cout &lt;&lt; &quot;接收：&quot; &lt;&lt; buffer &lt;&lt; endl;            buffer = &quot;ok&quot;;	// 生成回应报文内容            // 向对端发送报文            if(tcpserver.send(buffer) == false)            &#123;                perror(&quot;send&quot;);                break;            &#125;            cout &lt;&lt; &quot;发送：&quot; &lt;&lt; buffer &lt;&lt; endl;        &#125;                return 0;	// 子进程一定要退出，否则又会回到 accept() 函数的位置    &#125;&#125;// 父进程的信号处理函数void FathEXIT(int sig)&#123;    // 以下代码是为了防止信号处理函数在执行的过程中再次被信号中断    signal(SIGINT, SIG_IGN);    signal(SIGTERM, SIG_IGN);        cout &lt;&lt; &quot;父进程退出，sig=&quot; &lt;&lt; sig &lt;&lt; endl;        kill(0, SIGTERM);	// 向全部的子进程发送15的信号，通知它们退出        // 在这里增加释放资源的代码（全局的资源）    tcpserver.closelisten();	// 父进程关闭监听的 socket        exit(0);&#125;// 子进程的信号处理函数void ChldEXIT(int sig)&#123;    // 以下代码是为了防止信号处理函数在执行的过程中再次被信号中断    signal(SIGINT, SIG_IGN);    signal(SIGTERM, SIG_IGN);        cout &lt;&lt; &quot;子进程&quot; &lt;&lt; getpid() &lt;&lt; &quot;退出，sig=&quot; &lt;&lt; sig &lt;&lt; endl;        // 在这里增加释放资源的代码（只释放子进程的资源）    tcpserver.closeclient();	// 子进程关闭客户端连上来的 socket        exit(0);&#125;

