实现文件传输功能采用 socket 通讯，客户端把指定文件传输给服务端（支持文本文件和二进制文件）
/* * 程序名：demo8.cpp，此程序用于演示文件传输的客户端*/#include &lt;iostream&gt;#include &lt;fstream&gt;#include &lt;cstdio&gt;#include &lt;cstring&gt;#include &lt;cstdlib&gt;#include &lt;unistd.h&gt;#include &lt;netdb.h&gt;#include &lt;sys/types.h&gt;#include &lt;sys/socket.h&gt;#include &lt;arpa/inet.h&gt;using namespace std;class ctcpclient			// TCP 通讯的客户端类&#123;private:    int m_clientfd;			// 客户端的 socket，-1表示未连接或连接已断开；&gt;=0表示有效的 socket    string m_ip;			// 服务端的 IP /域名    unsigned short m_port;	 // 通讯端口    public:    ctcpclient() : m_clientfd(-1) &#123;&#125;        // 向服务端发起连接请求，成功返回 true，失败返回 false    bool connect(const string &amp;in_ip, const unsigned short in_port)    &#123;        if(m_clientfd != -1)	return false;	// 如果 socket 已连接，直接返回失败                // 把服务端的 IP 和端口保存到成员变量中        m_ip = in_ip;        m_port = in_port;                // 第1步：创建客户端的 socket        if((m_clientfd = socket(AF_INET, SOCK_STREAM, 0)) == -1)        &#123;            return false;        &#125;        // 第2步：向服务器发起连接请求        struct sockaddr_in servaddr;				// 用于存放协议、端口和 IP 地址的结构体        memset(&amp;servaddr, 0, sizeof(servaddr));        servaddr.sin_family = AF_INET;				// 1）协议族，固定填 AF_INET        servaddr.sin_port = htons(m_port);	// 2）指定服务端的通信端口                struct hostent* h;	// 用于存放服务器 IP 地址（大端序）的结构体的指针        if((h = gethostbyname(m_ip.c_str())) == nullptr)	// 把域名/主机名/字符串格式的 IP 转换成结构体        &#123;            ::close(m_clientfd);			// 全局 close 库函数            m_clientfd = -1;            return false;        &#125;        memcpy(&amp;servaddr.sin_addr, h-&gt;h_addr, h-&gt;h_length);		// 3）指定服务端的 IP（大端序）                // 向服务端发起连接请求        if(::connect(m_clientfd, (struct sockaddr*)&amp;servaddr, sizeof(servaddr)) == -1)		// 全局 connect 库函数        &#123;            ::close(m_clientfd);			// 全局 close 库函数            m_clientfd = -1;            return false;        &#125;                return true;    &#125;        // 向服务端发送报文（字符串），成功返回 true，失败返回 false    bool send(const string&amp; buffer)		// buffer 不要用 const char *    &#123;	    if(m_clientfd == -1)	return false;	// 如果 socket 的状态是未连接，直接返回失败                if((::send(m_clientfd, buffer.data(), buffer.size(), 0)) &lt;= 0) return false;	// 全局 send 库函数                return true;    &#125;    // 向服务端发送报文（二进制数据），成功返回 true，失败返回 false    bool send(void* buffer, const size_t size)    &#123;	    if(m_clientfd == -1)	return false;	// 如果 socket 的状态是未连接，直接返回失败                if((::send(m_clientfd, buffer, size, 0)) &lt;= 0) return false;	// 全局 send 库函数                return true;    &#125;               // 接收服务端的报文，成功返回 true，失败返回 false    // buffer-存放接收到的报文的内容，maxlen-本次接收报文的最大长度    bool recv(string&amp; buffer, const size_t maxlen)    &#123;	// 如果直接操作 string 对象的内存，必须保证：1）不能越界	2）操作后手动设置数据的大小        buffer.clear();			// 清空容器        buffer.resize(maxlen);	// 设置容器的大小为 maxlen        int readn = ::recv(m_clientfd, &amp;buffer[0], buffer.size(), 0);	// 直接操作 buffer 的内存，全局 recv 库函数        if(readn &lt;= 0)        &#123;            buffer.clear();            return false;        &#125;        buffer.resize(readn);	// 重置 buffer 的实际大小                return true;    &#125;               // 断开与服务端的连接    bool close()    &#123;        if(m_clientfd == -1) return false;	// 如果 socket 的状态是未连接，直接返回失败                ::close(m_clientfd);			// 全局 close 库函数        m_clientfd = -1;        return true;    &#125;               // 向服务端发送文件内容    bool sendfile(const string&amp; filename, const size_t filesize)    &#123;        // 以二进制的方式打开文件        ifstream fin(filename, ios::binary);        if(fin.is_open() == false)        &#123;            cout &lt;&lt; &quot;打开文件&quot; &lt;&lt; filename &lt;&lt; &quot;失败\n&quot;;            return false;        &#125;                int onread = 0;		// 每次调用 fin.read() 时打算读取的字节数        int totalbytes = 0;	// 从文件中已读取的字节总数        char buffer[4096];		// 存放读取数据的 buffer                while(true)        &#123;            memset(buffer, 0, sizeof(buffer));                        // 计算本次应该读取的字节数，如果剩余的数据超过4096字节，就读4096字节            if(filesize - totalbytes &gt; 4096) onread = 4096;            else onread = filesize - totalbytes;                        // 从文件中读取数据            fin.read(buffer, onread);                        // 把读取到的数据发送给对端            if(send(buffer, onread) == false)	return false;                        // 计算文件已读取的字节总数，如果文件已读完，跳出循环            totalbytes = totalbytes + onread;                        if(totalbytes == filesize)	break;        &#125;        return true;    &#125;    ~ctcpclient()     &#123;    	close();               &#125;&#125;;int main(int argc, char* argv[])&#123;    if(argc != 5)    &#123;        cout &lt;&lt; &quot;Using: ./demo8 服务端的 IP 服务端的端口 文件名 文件大小\n&quot;;        cout &lt;&lt; &quot;Example: ./demo8 192.168.112.131 5005 aaa.txt 2424\n\n&quot;;        return -1;    &#125;        ctcpclient tcpclient;    if(tcpclient.connect(argv[1], atoi(argv[2])) == false)	// 向服务端发起连接请求    &#123;        perror(&quot;connect()&quot;);        return -1;    &#125;        // 以下是发送文件的流程    // 1）把待传输文件名和文件的大小告诉服务端    // 定义文件信息的结构体    struct st_fileinfo&#123;        char filename[256];		// 文件名        int filesize;			// 文件大小    &#125;fileinfo;    memset(&amp;fileinfo, 0, sizeof(fileinfo));    strcpy(fileinfo.filename, argv[3]);		// 文件名    fileinfo.filesize = atoi(argv[4]);		// 文件大小    // 把文件信息的结构体发送给服务端    if(tcpclient.send(&amp;fileinfo, sizeof(fileinfo)) == false)    &#123;        perror(&quot;send&quot;);        return -1;    &#125;    cout &lt;&lt; &quot;发送文件信息的结构体&quot; &lt;&lt; fileinfo.filename &lt;&lt; &quot;(&quot; &lt;&lt; fileinfo.filesize &lt;&lt; &quot;)&quot; &lt;&lt; endl;        // 2）等待服务端的确认报文（文件名和文件的大小的确认）    string buffer;    if(tcpclient.recv(buffer, 2) == false)    &#123;        perror(&quot;recv()&quot;);        return -1;    &#125;    if(buffer != &quot;ok&quot;)    &#123;        cout &lt;&lt; &quot;服务端没有回复ok\n&quot;;        return -1;    &#125;    // 3）发送文件内容    if(tcpclient.sendfile(fileinfo.filename, fileinfo.filesize) == false)    &#123;    	perror(&quot;sendfile()&quot;);         return -1;    &#125;        // 4）等待服务端的确认报文（服务端已接收完文件）    if (tcpclient.recv(buffer,2)==false) &#123; perror(&quot;recv()&quot;); return -1; &#125;	if (buffer!=&quot;ok&quot;)     &#123;         cout &lt;&lt; &quot;发送文件内容失败\n&quot;;        return -1;    &#125;	cout &lt;&lt; &quot;发送文件内容成功\n&quot;;&#125;

/* * 程序名：demo9.cpp，此程序用于演示文件传输的服务端*/#include &lt;iostream&gt;#include &lt;fstream&gt;#include &lt;cstdio&gt;#include &lt;cstring&gt;#include &lt;cstdlib&gt;#include &lt;unistd.h&gt;#include &lt;signal.h&gt;#include &lt;netdb.h&gt;#include &lt;sys/types.h&gt;#include &lt;sys/socket.h&gt;#include &lt;arpa/inet.h&gt;using namespace std;class ctcpserver		// TCP通讯的服务端类&#123;private:    int		m_listenfd;		// 监听的 socket, -1表示未初始化    int		m_clientfd;		// 客户端连上来的 socket，-1表示客户端未连接    string	m_clientip;		// 客户端的 IP    unsigned short m_port;	// 服务端用于通讯的端口public:    ctcpserver() : m_listenfd(-1), m_clientfd(-1) &#123;&#125;        // 初始化服务端用于监听的 socket    bool initserver(const unsigned short in_port)    &#123;        // 第1步：创建服务端的 socket        if((m_listenfd = socket(AF_INET, SOCK_STREAM, 0)) == -1) return false;                m_port = in_port;        // 第2步：把服务端用于通信的 IP 和端口绑定到 socket 上        struct sockaddr_in servaddr;	// 用于存放协议、端口和 IP 地址的结构体        memset(&amp;servaddr, 0, sizeof(servaddr));        servaddr.sin_family = AF_INET;		// 1）协议族，固定填 AF_INET        servaddr.sin_port = htons(m_port);	// 2）指定服务端的通信端口        servaddr.sin_addr.s_addr = htonl(INADDR_ANY);	// 3）如果操纵系统有多个 IP，全部的 IP 都可以用于通讯                // 绑定服务端的 IP 和端口（为 socket 分配 IP 和端口）        if(bind(m_listenfd, (struct sockaddr*)&amp;servaddr, sizeof(servaddr)) == -1)        &#123;            close(m_listenfd);            m_listenfd = -1;            return false;        &#125;        // 第3步：把 socket 设置为可连接（监听）的状态        if(listen(m_listenfd, 5) == -1)        &#123;            close(m_listenfd);            m_listenfd = -1;            return false;        &#125;                return true;    &#125;        // 受理客户端的连接（从已连接的客户端中取出一个客户端），如果没有已连接的客户端，accept() 函数将阻塞等待    bool accept()    &#123;        struct sockaddr_in caddr;			// 客户端的地址信息        socklen_t addrlen = sizeof(caddr);	 // struct sockaddr_in 的大小        if((m_clientfd = ::accept(m_listenfd, (struct sockaddr*)&amp;caddr, &amp;addrlen)) == -1) return false;	// 全局 accept 库函数                m_clientip = inet_ntoa(caddr.sin_addr);		// 客户端的地址从大端序转换成字符串                return true;    &#125;        // 获取客户端的 IP（字符串格式）    const string&amp; clientip() const    &#123;        return m_clientip;    &#125;        // 向对端发送报文，成功返回 true，失败返回 false    bool send(const string&amp; buffer)    &#123;        if(m_clientfd == -1) return false;                if((::send(m_clientfd, buffer.data(), buffer.size(), 0)) &lt;= 0) return false;	// 全局 send 库函数                return true;    &#125;        // 接收对端的报文，成功返回 true，失败返回 false    // buffer-存放接收到的报文的内容，maxlen-本次接收报文的最大长度    bool recv(string&amp; buffer, const size_t maxlen)    &#123;        buffer.clear();			// 清空容器        buffer.resize(maxlen);	// 设置容器的大小为 maxlen        int readn = ::recv(m_clientfd, &amp;buffer[0], buffer.size(), 0);	// 直接操作 buffer 的内存，全局 recv 库函数        if(readn &lt;= 0)        &#123;            buffer.clear();            return false;        &#125;        buffer.resize(readn);	// 重置 buffer 的实际大小                return true;    &#125;        // 接收客户端的报文（二进制数据），成功返回 true，失败返回 false    // buffer-存放接收到的报文的内容，size-本次接收报文的最大长度    bool recv(void* buffer, const size_t size)    &#123;        if(::recv(m_clientfd, buffer, size, 0) &lt;= 0)	// 全局 recv 库函数        &#123;            return false;        &#125;                return true;    &#125;        // 关闭监听的 socket    bool closelisten()    &#123;        if(m_listenfd == -1)	return false;                close(m_listenfd);	        m_listenfd = -1;        return true;    &#125;        // 关闭客户端连上来的 socket    bool closeclient()    &#123;        if(m_clientfd == -1) return false;                close(m_clientfd);        m_clientfd = -1;        return true;    &#125;        // 接收文件内容	bool recvfile(const string&amp; filename, const size_t filesize)    &#123;    	ofstream fout;    	fout.open(filename, ios::binary);    	if (fout.is_open() == false)         &#123;             cout &lt;&lt; &quot;打开文件&quot;&lt;&lt; filename &lt;&lt; &quot;失败\n&quot;;            return false;         &#125;            int totalbytes=0;	// 已接收文件的总字节数    	int onread=0;		// 本次打算接收的字节数    	char buffer[4096];	// 接收文件内容的缓冲区            while (true)        &#123;        	// 计算本次应该接收的字节数            if(filesize - totalbytes &gt; 4096) onread = 4096;            else onread = filesize - totalbytes;                        // 接收文件内容            if(recv(buffer ,onread) == false) return false;                        // 把接收到的内容写入文件            fout.write(buffer, onread);            // 计算已接收文件的总字节数，如果文件接收完，跳出循环            totalbytes = totalbytes + onread;                        if(totalbytes == filesize) break;        &#125;    	return true;    &#125;        ~ctcpserver()     &#123;         closelisten();         closeclient();     &#125;&#125;;ctcpserver tcpserver;void FathEXIT(int sig);		// 父进程的信号处理函数void ChldEXIT(int sig);		// 子进程的信号处理函数int main(int argc, char* argv[])&#123;    if(argc != 3)    &#123;        cout &lt;&lt; &quot;Using: ./demo9 通讯端口 文件存放的目录\n&quot;;        cout &lt;&lt; &quot;Example: ./demo9 5005 /tmp\n\n&quot;;        cout &lt;&lt; &quot;注意：运行服务端程序的 Linux 系统的防火墙必须要开通5005端口\n&quot;;        cout &lt;&lt; &quot;	如果是云服务器，还要开通云平台的访问策略\n\n&quot;;        return -1;    &#125;        // 忽略全部的信号，不希望被打扰，顺便解决了僵尸进程的问题    for(int ii = 1; ii &lt;= 64; ii++)	signal(ii, SIG_IGN);        // 设置信号，在 shell 状态下可用 &quot;kill 进程号&quot; 或 &quot;Ctrl+c&quot; 正常终止进程    // 但请不要用 &quot;kill -9 +进程号&quot; 强行终止    signal(SIGTERM, FathEXIT);    signal(SIGINT, FathEXIT);	// SIGTERM 15 SIGINT 2        if(tcpserver.initserver(atoi(argv[1])) == false)	// 初始化服务端用于监听的 socket    &#123;        perror(&quot;initserver()&quot;);        return -1;    &#125;        while(true)    &#123;        // 受理客户端的连接（从已连接的客户端中取出一个客户端），如果没有已连接的客户端，accept() 函数将阻塞等待        if(tcpserver.accept() == false)        &#123;            perror(&quot;accept()&quot;);            return -1;        &#125;                int pid = fork();        if(pid == -1)	// 系统资源不足        &#123;            perror(&quot;fork()&quot;);            return -1;        &#125;        if(pid &gt; 0)		// 父进程        &#123;            tcpserver.closeclient();	// 父进程关闭客户端连接的 socket            continue;				// 父进程返回到循环开始的位置，继续受理客户端的连接        &#125;                tcpserver.closelisten();		// 子进程关闭监听的 socket                // 子进程需要重新设置信号        signal(SIGTERM, ChldEXIT);		// 子进程的退出函数与父进程不一样        signal(SIGINT, SIG_IGN);		// 子进程不需要捕获 SIGINT 信号                // 子进程负责与客户端进行通讯        cout &lt;&lt; &quot;客户端已连接(&quot; &lt;&lt;tcpserver.clientip() &lt;&lt; &quot;)\n&quot;;        // 以下是接收文件的流程        // 1）接收文件名和文件大小信息        // 定义文件信息的结构体        struct st_fileinfo&#123;            char filename[256];		// 文件名            int filesize;			// 文件大小        &#125;fileinfo;        memset(&amp;fileinfo, 0, sizeof(fileinfo));        // 用结构体存放接收报文的内容        if(tcpserver.recv(&amp;fileinfo, sizeof(fileinfo)) == false)        &#123;            perror(&quot;recv()&quot;);            return -1;        &#125;        cout &lt;&lt; &quot;文件信息结构体&quot; &lt;&lt; fileinfo.filename &lt;&lt; &quot;(&quot; &lt;&lt; fileinfo.filesize &lt;&lt; &quot;)&quot; &lt;&lt; endl;                // 2）给客户端回复确认报文，表示客户端可以发送文件了        if(tcpserver.send(&quot;ok&quot;) == false)        &#123;            perror(&quot;send&quot;);            break;        &#125;                // 3）接收文件内容			string		char * + const char * + char *	string 才能相加        if(tcpserver.recvfile(string(argv[2]) + &quot;/&quot; + fileinfo.filename, fileinfo.filesize) == false)        &#123;            cout &lt;&lt; &quot;接收文件内容失败\n&quot;;             return -1;        &#125;        cout &lt;&lt; &quot;接收文件内容成功\n&quot;;                // 4）给客户端回复确认报文，表示文件已接收成功        tcpserver.send(&quot;ok&quot;);                return 0;	// 子进程一定要退出，否则又会回到 accept() 函数的位置    &#125;&#125;// 父进程的信号处理函数void FathEXIT(int sig)&#123;    // 以下代码是为了防止信号处理函数在执行的过程中再次被信号中断    signal(SIGINT, SIG_IGN);    signal(SIGTERM, SIG_IGN);        cout &lt;&lt; &quot;父进程退出，sig=&quot; &lt;&lt; sig &lt;&lt; endl;        kill(0, SIGTERM);	// 向全部的子进程发送15的信号，通知它们退出        // 在这里增加释放资源的代码（全局的资源）    tcpserver.closelisten();	// 父进程关闭监听的 socket        exit(0);&#125;// 子进程的信号处理函数void ChldEXIT(int sig)&#123;    // 以下代码是为了防止信号处理函数在执行的过程中再次被信号中断    signal(SIGINT, SIG_IGN);    signal(SIGTERM, SIG_IGN);        cout &lt;&lt; &quot;子进程&quot; &lt;&lt; getpid() &lt;&lt; &quot;退出，sig=&quot; &lt;&lt; sig &lt;&lt; endl;        // 在这里增加释放资源的代码（只释放子进程的资源）    tcpserver.closeclient();	// 子进程关闭客户端连上来的 socket        exit(0);&#125;

