三次握手与四次挥手TCP 是面向连接的、可靠的协议，建立 TCP 连接需要三次对话（三次握手），拆除 TCP 连接需要四次对话（四次握&#x2F;挥手）
三次握手服务端调用 listen() 函数后进入监听（等待连接）状态，这时候，客户端就可以调用 connect() 函数发起 TCP 连接请求客户端调用 connect() 函数的时候会触发三次握手三次握手完成后，客户端与服务端将建立一个双向的传输通道
.juulqcvdmmcc{zoom:67%;}


客户端的 socket 也有端口号，对程序员来说，不必关心客户端 socket 的端口号，因为系统随机分配（socket 通讯中的地址包括 ip 和端口号，但是，习惯中的地址仅指 ip 地址）
服务端的 bind() 函数，普通用户只能使用1024以上的端口，root 用户可以使用任意端口
listen() 函数的第二个参数+1为已连接队列（ESTABLISHED状态，三次握手已完成但是没有被 accept() 的 socket，只存在于服务端）的大小（在高并发的服务程序中，该参数应该调大一些）
SYN_RECV 状态的连接也称为半连接
CLOSED 是假想状态，实际上不存在

四次挥手（握手）断开一个 TCP 连接时，需要客户端和服务端相互总共发送四个包以确认连接的断开在 socket 编程中，这一过程由客户端或服务端任一方执行 close() 函数触发
.wwuqjlvmaeio{zoom:67%;}


主动断开的端在四次挥手后，socket 的状态为 TIME_WAIT，该状态将持续 2MSL（30秒&#x2F;1分钟&#x2F;2分钟）MSL（Maximum Segment Lifetime）报文在网络上存在的最长时间，超过这个时间报文将被丢弃

如果是客户端主动断开，TIME_WAIT 状态的 socket 几乎不会造成危害1）客户端程序的 socket 很少，服务端程序很多（成千上万）2）客户端的端口是随机分配的，不存在重用的问题

如果是服务端主动断开，有两方面危害1）socket 没有立即释放2）端口号只能在 2MSL 后才能重用在服务端程序中，用 setsockopt() 函数设置 socket 的属性（一定要放在 bind() 之前）
int opt = 1;setsockopt(m_listenfd, SOL_SOCKET, SO_REUSEADDR, &amp;opt, sizeof(opt));

TCP 缓存系统为每个 socket 创建了发送缓冲区和接收缓冲区应用程序调用 send()&#x2F;write() 函数发送数据的时候，内核把数据从应用进程拷贝到 socket 的发送缓冲区中应用程序调用 recv()&#x2F;read() 函数接收数据的时候，内核把数据从 socket 的接收缓冲区拷贝到应用进程中发送数据即把数据放入发送缓冲区接收数据即从接收缓冲区中去数据
.yhsyxjxwlqgx{zoom:67%;}

查看 socket 缓存的大小
int bufsize = 0;socklen_t optlen = sizeof(bufsize);getsockopt(sockfd, SOL_SOCKET, SO_SNDBUF, &amp;bufsize, &amp;optlen);	// 获取发送缓冲区的大小cout &lt;&lt; &quot;send bufsize=&quot; &lt;&lt; bufsize &lt;&lt; endl;getsockopt(sockfd, SOL_SOCKET, SO_RCVBUF, &amp;bufsize, &amp;optlen);	// 获取接收缓冲区的大小cout &lt;&lt; &quot;recv bufsize=&quot; &lt;&lt; bufsize &lt;&lt; endl;


send() 函数有可能会阻塞吗如果自己的发送缓冲区和对端的接收缓冲区都满了，会阻塞

向 socket 中写入数据后，如果关闭了 socket，对端还能接收到数据吗对端能够接收到数据

Nagle 算法在 TCP 协议中，无论发送多少数据，都要在数据前面加上协议头，同时，对方收到数据后，也需要回复 ACK 表示确认为了尽可能的利用网络带宽，TCP 希望每次都能够以 MSS（Maximum Segment Size，最大报文长度）的数据块来发送数据Nagle 算法就是为了尽可能发送大块的数据，避免网络中充斥着小数据块Nagle 算法的定义是：任意时刻，最多只能有一个未被确认的小段，小段是指小于 MSS 的数据块，未被确认是指一个数据块发送出去后，没有收到对端回复的 ACK例如，发送端调用 send() 函数将一个 int 型数据（称之为 A 数据块）写入到 socket 中，A 数据块会被马上发送到接收端，接着，发送端又调用 send() 函数写入一个 int 型数据（称之为 B 数据块），这时候，A 块的 ACK 没有返回（已经存在了一个未被确认的小段），所以 B 块不会立即被发送，而是等 A 块的 ACK 返回之后（大概40ms）才发送TCP协议中不仅仅有 Nagle 算法，还有一个 ACK 延迟机制：当接收端收到数据之后，并不会马上向发送端回复 ACK，而是延迟40ms后再回复，它希望在40ms内接收端会向发送端回复应答数据，这样 ACK 就可以和应答数据一起发送，把 ACK 捎带过去如果 TCP 连接的一端启用了 Nagle 算法，另一端启用了 ACK 延时机制，而发送的数据包又比较小，则可能出现这样的情况：发送端在等待上一个包的 ACK，而接收端正好延迟了此 ACK，那么这个正要被发送的包就会延迟 40ms解决方案开启 TCP_NODELAY 选项，这个选项的作用就是禁用 Nagle 算法
#include &lt;netinet/tcp.h&gt;		// 注意，要包含这个头文件int opt = 1;setsockopt(sockfd, IPPROTO_TCP, TCP_NODELAY, &amp;opt, sizeof(opt));

对时效要求很高的系统，例如联机游戏、证券交易，一般会禁用 Nagle 算法


I&#x2F;O 多路复用
用一个进&#x2F;线程处理多个 TCP 连接，减少系统开销
三种模型：select（1024）、poll（数千）和 epoll（百万）

网络通讯-写事件发送缓冲区没有满，可以写入数据（可以向对端发送报文）
网络通讯-读事件
已连接队列中有已经准备好的 socket（有新的客户端连上来）
接收缓存中有数据可以读（对端发送的报文已到达）
TCP 连接已断开（对端调用 close() 函数关闭了连接）

select 模型/* According to POSIX.1-2001 */#include &lt;sys/select.h&gt;/* According to earlier standards */#include &lt;sys/time.h&gt;#include &lt;sys/types.h&gt;#include &lt;unistd.h&gt;int select(int nfds, fd_set *readfds, fd_set *writefds, fd_set *exceptfds, struct timeval *timeout);void FD_CLR(int fd, fd_set *set);		// 把 socket 从 bitmap 中删除int  FD_ISSET(int fd, fd_set *set);		// 判断 socket 是否在 bitmap 中void FD_SET(int fd, fd_set *set);		// 把 socket 加入到集合中void FD_ZERO(fd_set *set);			// 初始化位图，全部置为0

select 模型-性能测试/* * 程序名：tcpselect.cpp，此程序用于演示采用 select 模型实现网络通讯的服务端 **/#include &lt;stdio.h&gt;#include &lt;unistd.h&gt;#include &lt;stdlib.h&gt;#include &lt;string.h&gt;#include &lt;sys/socket.h&gt;#include &lt;arpa/inet.h&gt;#include &lt;sys/fcntl.h&gt;// 初始化服务端的监听端口int initserver(int port);int main(int argc, char* argv[])&#123;    if(argc != 2)    &#123;        printf(&quot;usage: ./tcpselect port\n&quot;);        return -1;    &#125;        // 初始化服务端用于监听的 socket    int listensock = initserver(atoi(argv[1]));    printf(&quot;listensock=%d\n&quot;, listensock);        if(listensock &lt; 0)    &#123;        printf(&quot;initserver() failed\n&quot;);        return -1;    &#125;        fd_set readfds;					// 需要监视读事件的 socket 的集合，大小为16字节（1024位）的 bitmap    FD_ZERO(&amp;readfds);				// 初始化 readfds，把 bitmap 的每一位都置为0    FD_SET(listensock, &amp;readfds);	// 把服务端用于监听的 socket 加入 readfds        int maxfd = listensock;			// readfds 中 socket 的最大值        while(true)    &#123;        // 用于表示超时时间的结构体        struct timeval timeout;        timeout.tv_sec = 10;		// 秒        timeout.tv_usec = 0;		// 微秒                // 在 select() 函数中，会修改 bitmap，所以，要把 readfds 复制一份给 tmpfds，再把 tmpfds 传给 select()        fd_set tmpfds = readfds;                // select() 等待事件的发生（监视哪些 socket 发生了事件）        int infds = select(maxfd + 1, &amp;tmpfds, NULL, NULL, &amp;timeout);                // 如果 infds &lt; 0，表示调用 select() 失败        if(infds &lt; 0)        &#123;            perror(&quot;select() failed&quot;);            break;        &#125;                // 如果 infds == 0，表示 select() 超时        if(infds == 0)        &#123;            printf(&quot;select() timeout\n&quot;);            continue;        &#125;                // 如果 infds &gt; 0，表示有事件发生，infds 存放了已发生事件的个数        for(int eventfd = 0; eventfd &lt;= maxfd; eventfd++)        &#123;            // 如果 eventfd 在 bitmap 中的标志为0，表示它没有事件，continue            if(FD_ISSET(eventfd, &amp;tmpfds) == 0) continue;                        // 如果发生事件的是 listensock，表示已连接队列中有已经准备好的 socket（有新的客户端连上来了）            if(eventfd == listensock)            &#123;                struct sockaddr_in client;                socklen_t len = sizeof(client);                int clientsock = accept(listensock, (struct sockaddr*)&amp;client, &amp;len);                if(clientsock &lt; 0)                &#123;                    perror(&quot;accept() failed&quot;);                    continue;                &#125;                                printf(&quot;accept client(socket=%d) ok\n&quot;, clientsock);                                // 把 bitmap 中新连上来的客户端的标志位置为1                FD_SET(clientsock, &amp;readfds);                                // 更新 maxfd 的值                if(maxfd &lt; clientsock)	maxfd = clientsock;            &#125;else            &#123;                // 如果是客户端连接的 socket 有事件，表示接收缓存中有数据可以读（对端发送的报文已到达），或者有客户端已断开连接                char buffer[1024];			// 存放从客户端读取的数据                memset(buffer, 0, sizeof(buffer));                if(recv(eventfd, buffer, sizeof(buffer), 0) &lt;= 0)                &#123;                    // 如果客户端的连接已断开                    printf(&quot;client(eventfd=%d) disconnected\n&quot;, eventfd);                                        close(eventfd);				// 关闭客户端的 socket                                        FD_CLR(eventfd, &amp;readfds);	// 把 bitmap 中已关闭客户端的标志位清空                                        if(eventfd == maxfd)		// 重新计算 maxfd 的值，注意，只要当 eventfd == maxfd 时才需要计算                    &#123;                        for(int ii = maxfd; ii &gt; 0; ii--)	// 从后面往前找                        &#123;                            if(FD_ISSET(ii, &amp;readfds))                            &#123;                                maxfd = ii;                                break;                            &#125;                        &#125;                    &#125;                &#125;else                &#123;                    // 如果客户端有报文发过来                    printf(&quot;recv(eventfd=%d):%s\n&quot;, eventfd, buffer);                                        // 把接收到的报文内容原封不动的发回去                    send(eventfd, buffer, strlen(buffer), 0);                &#125;            &#125;        &#125;    &#125;        return 0;&#125;// 初始化服务端的监听端口int initserver(int port)&#123;    int sock = socket(AF_INET, SOCK_STREAM, 0);    if(sock &lt; 0)    &#123;        perror(&quot;socket() failed&quot;);        return -1;    &#125;        int opt = 1;    unsigned int len = sizeof(opt);    setsockopt(sock, SOL_SOCKET, SO_REUSEADDR, &amp;opt, len);        struct sockaddr_in servaddr;    servaddr.sin_family = AF_INET;    servaddr.sin_addr.s_addr = htonl(INADDR_ANY);    servaddr.sin_port = htons(port);        if(bind(sock, (struct sockaddr*)&amp;servaddr, sizeof(servaddr)) &lt; 0)    &#123;        perror(&quot;bind() failed&quot;);        close(sock);        return -1;    &#125;        if(listen(sock, 5) != 0)    &#123;        perror(&quot;listen() failed&quot;);        close(sock);        return -1;    &#125;        return sock;&#125;

/* * 程序名：client.cpp，此程序用于演示采用 select 模型实现网络通讯的客户端*/#include &lt;stdio.h&gt;#include &lt;stdlib.h&gt;#include &lt;unistd.h&gt;#include &lt;errno.h&gt;#include &lt;string.h&gt;#include &lt;netinet/in.h&gt;#include &lt;sys/socket.h&gt;#include &lt;arpa/inet.h&gt;int main(int argc, char* argv[])&#123;    if(argc != 3)    &#123;        printf(&quot;usage: ./client ip port\n&quot;);        return -1;    &#125;        int sockfd;    struct sockaddr_in servaddr;    char buf[1024];        if((sockfd = socket(AF_INET, SOCK_STREAM, 0)) &lt; 0)    &#123;        printf(&quot;socket() failed\n&quot;);        return -1;    &#125;        memset(&amp;servaddr, 0, sizeof(servaddr));    servaddr.sin_family = AF_INET;    servaddr.sin_port = htons(atoi(argv[2]));    servaddr.sin_addr.s_addr = inet_addr(argv[1]);        if(connect(sockfd, (struct sockaddr*)&amp;servaddr, sizeof(servaddr)) != 0)    &#123;        printf(&quot;connect(%s:%s) failed\n&quot;, argv[1], argv[2]);        close(sockfd);        return -1;    &#125;        printf(&quot;connect ok\n&quot;);    for(int ii = 0; ii &lt; 1000000; ii++)    &#123;        // 从命令行输入内容        memset(buf, 0, sizeof(buf));        printf(&quot;please input:&quot;);        scanf(&quot;%s&quot;, buf);                if(send(sockfd, buf, strlen(buf), 0) &lt;= 0)        &#123;            printf(&quot;write() failed\n&quot;);            close(sockfd);            return -1;        &#125;                memset(buf, 0, sizeof(buf));        if(recv(sockfd, buf, sizeof(buf), 0) &lt;= 0)        &#123;            printf(&quot;read() failed\n&quot;);            close(sockfd);            return -1;        &#125;                printf(&quot;recv:%s\n&quot;, buf);    &#125;&#125;

