select 模型-写事件
如果 TCP 的发送缓冲区没有满，那么，socket 连接是可写的
一般来说，发送缓冲区不容易被填满
如果发送的数据量太大，或网络带宽不够，发送缓冲区有填满的可能
select 监视写事件，如果发送缓冲区没有满，select 函数会立即返回

select 模型-水平触发
select() 监视的 socket 如果发生了事件，select() 会返回（通知应用程序处理事件）
如果事件没有被处理，再次调用 select() 的时候会立即再通知

select 模型-存在的问题
采用轮询方式扫描 bitmap，性能会随着 socket 数量增多而下降
select() 会修改 bitmap，每次调用 select() 前，需要拷贝一份 bitmap，程序运行在用户态，网络通信在内核，调用 select() 的时候，要把 bitmap 从用户态拷贝一份到内核态，bitmap 总共需要拷贝两次
bitmap 的大小（单个进&#x2F;线程打开的 socket 数量）由 FD_SETSIZE 宏设置，默认是1024个，可以修改，但是效率将更低

poll 模型struct pollfd &#123;    int   fd;         /* file descriptor */    short events;     /* requested events */    short revents;    /* returned events */&#125;;// poll 事件POLLIN     There is data to read.POLLPRI    There is urgent data to read (e.g., out-of-band  data  on TCP socket; pseudoterminal master in packet mode has seen state change in slave).POLLOUT    Writing now will not block.

poll模型-性能测试/* * 程序名：tcppoll.cpp，此程序用于演示采用 poll 模型实现网络通讯的服务端 **/#include &lt;stdio.h&gt;#include &lt;unistd.h&gt;#include &lt;stdlib.h&gt;#include &lt;string.h&gt;#include &lt;poll.h&gt;#include &lt;sys/socket.h&gt;#include &lt;arpa/inet.h&gt;#include &lt;sys/fcntl.h&gt;// 初始化服务端的监听端口int initserver(int port);int main(int argc, char* argv[])&#123;    if(argc != 2)    &#123;        printf(&quot;usage: ./tcppoll port\n&quot;);        return -1;    &#125;        // 初始化服务端用于监听的 socket    int listensock = initserver(atoi(argv[1]));    printf(&quot;listensock=%d\n&quot;, listensock);        if(listensock &lt; 0)    &#123;        printf(&quot;initserver() failed\n&quot;);        return -1;    &#125;        pollfd fds[2048];			// fds 存放需要监视的 socket        // 初始化数组，把全部的 socket 设置为-1，如果数组中的 socket 的值为-1，那么，poll 将忽略它    for(int ii = 0; ii &lt; 2048; ii++)	fds[ii].fd = -1;        // 打算让 poll 监视 listensock 读事件    fds[listensock].fd = listensock;    fds[listensock].events = POLLIN;		// POLLIN 表示读事件，POLLOUT 表示写事件    // fds[listensock].events = POLLIN|POLLOUT;        int maxfd = listensock;			// fds 数组中需要监视的 socket 的实际大小        while(true)    &#123;        // 调用 poll() 等待事件的发生（监视哪些 socket 发生了事件）        int infds = poll(fds, maxfd+1, 10000);		// 超时时间为10秒                // 如果 infds &lt; 0，表示调用 poll() 失败        if(infds &lt; 0)        &#123;            perror(&quot;poll() failed&quot;);            break;        &#125;                // 如果 infds == 0，表示 poll() 超时        if(infds == 0)        &#123;            printf(&quot;poll() timeout\n&quot;);            continue;        &#125;                // 如果 infds &gt; 0，表示有事件发生，infds 存放了已发生事件的个数        for(int eventfd = 0; eventfd &lt;= maxfd; eventfd++)        &#123;            // 如果 fd 为负，忽略它            if(fds[eventfd].fd &lt; 0) continue;                        // 如果没有读事件，continue            if((fds[eventfd].revents&amp;POLLIN) == 0) continue;                        // 如果发生事件的是 listensock，表示已连接队列中有已经准备好的 socket（有新的客户端连上来了）            if(eventfd == listensock)            &#123;                struct sockaddr_in client;                socklen_t len = sizeof(client);                int clientsock = accept(listensock, (struct sockaddr*)&amp;client, &amp;len);                if(clientsock &lt; 0)                &#123;                    perror(&quot;accept() failed&quot;);                    continue;                &#125;                                printf(&quot;accept client(socket=%d) ok\n&quot;, clientsock);                                // 修改 fds 数组中 clientsock 位置的元素                fds[clientsock].fd = clientsock;                fds[clientsock].events = POLLIN;                                // 更新 maxfd 的值                if(maxfd &lt; clientsock)	maxfd = clientsock;            &#125;else            &#123;                // 如果是客户端连接的 socket 有事件，表示有报文发过来了或者连接已断开                char buffer[1024];			// 存放从客户端读取的数据                memset(buffer, 0, sizeof(buffer));                if(recv(eventfd, buffer, sizeof(buffer), 0) &lt;= 0)                &#123;                    // 如果客户端的连接已断开                    printf(&quot;client(eventfd=%d) disconnected\n&quot;, eventfd);                                        close(eventfd);				// 关闭客户端的 socket                    fds[eventfd].fd = -1;		// 修改 fds 数组中 clientsock 位置的元素，置为-1，poll将忽略该元素                                        if(eventfd == maxfd)		// 重新计算 maxfd 的值，注意，只要当 eventfd == maxfd 时才需要计算                    &#123;                        for(int ii = maxfd; ii &gt; 0; ii--)	// 从后面往前找                        &#123;                            if(fds[ii].fd != -1)                            &#123;                                maxfd = ii;                                break;                            &#125;                        &#125;                    &#125;                &#125;else                &#123;                    // 如果客户端有报文发过来                    printf(&quot;recv(eventfd=%d):%s\n&quot;, eventfd, buffer);                                        // 把接收到的报文内容原封不动的发回去                    send(eventfd, buffer, strlen(buffer), 0);                &#125;            &#125;        &#125;    &#125;        return 0;&#125;// 初始化服务端的监听端口int initserver(int port)&#123;    int sock = socket(AF_INET, SOCK_STREAM, 0);    if(sock &lt; 0)    &#123;        perror(&quot;socket() failed&quot;);        return -1;    &#125;        int opt = 1;    unsigned int len = sizeof(opt);    setsockopt(sock, SOL_SOCKET, SO_REUSEADDR, &amp;opt, len);        struct sockaddr_in servaddr;    servaddr.sin_family = AF_INET;    servaddr.sin_addr.s_addr = htonl(INADDR_ANY);    servaddr.sin_port = htons(port);        if(bind(sock, (struct sockaddr*)&amp;servaddr, sizeof(servaddr)) &lt; 0)    &#123;        perror(&quot;bind() failed&quot;);        close(sock);        return -1;    &#125;        if(listen(sock, 5) != 0)    &#123;        perror(&quot;listen() failed&quot;);        close(sock);        return -1;    &#125;        return sock;&#125;

