poll 模型-写事件
如果 TCP 的发送缓冲区没有满，那么，socket 连接是可写的
一般来说，发送缓冲区不容易被填满
如果发送的数据量太大，或网络带宽不够，发送缓冲区有填满的可能

poll 模型-水平触发
poll() 监视的 socket 如果发生了事件，poll() 会返回（通知应用程序处理事件）
如果事件没有被处理，再次调用 poll() 的时候会立即再通知

poll 模型-存在的问题
在程序中，poll 的数据结构是数组，传入内核后转换成了链表
每调用一次 select() 需要拷贝两次 bitmap，poll 拷贝一次结构体数组
poll 监视的连接数没有1024的限制，但是也是遍历的方法，监视的 socket 越多，效率越低

epoll 模型// creates  an  epoll(7) instance.  Since Linux 2.6.8, the size argument is ignored, but must be  greater  than  zero;  see  NOTES belowint epoll_create(int size);typedef union epoll_data &#123;    void        *ptr;    int          fd;    uint32_t     u32;    uint64_t     u64;&#125; epoll_data_t;struct epoll_event &#123;    uint32_t     events;      /* Epoll events */    epoll_data_t data;        /* User data variable */&#125;;

epoll 模型-性能测试/* * 程序名：tcpepoll.cpp，此程序用于演示采用 epoll 模型实现网络通讯的服务端 **/#include &lt;stdio.h&gt;#include &lt;unistd.h&gt;#include &lt;stdlib.h&gt;#include &lt;string.h&gt;#include &lt;errno.h&gt;#include &lt;sys/socket.h&gt;#include &lt;sys/types.h&gt;#include &lt;arpa/inet.h&gt;#include &lt;sys/fcntl.h&gt;#include &lt;sys/epoll.h&gt;// 初始化服务端的监听端口int initserver(int port);int main(int argc, char* argv[])&#123;    if(argc != 2)    &#123;        printf(&quot;usage: ./tcpepoll port\n&quot;);        return -1;    &#125;        // 初始化服务端用于监听的 socket    int listensock = initserver(atoi(argv[1]));    printf(&quot;listensock=%d\n&quot;, listensock);        if(listensock &lt; 0)    &#123;        printf(&quot;initserver() failed\n&quot;);        return -1;    &#125;       // 创建 epoll 句柄    int epollfd = epoll_create(1);        // 为服务端的 listensock 准备可读事件    epoll_event ev;				// 声明事件的数据结构    ev.data.fd = listensock;	// 指定事件的自定义数据，会随着 epoll_wait() 返回的事件一并返回    ev.events = EPOLLIN;		// 打算让 epoll 监视 listensock 的读事件        epoll_ctl(epollfd, EPOLL_CTL_ADD, listensock, &amp;ev);		// 把需要监视的 socket 加入 epollfd 中        epoll_event evs[10];		// 存放 epoll 返回的事件        while(true)    &#123;        // 等待监视的 socket 有事件发生        int infds = epoll_wait(epollfd, evs, 10, -1);                // 如果 infds &lt; 0，表示调用 epoll_wait() 失败        if(infds &lt; 0)        &#123;            perror(&quot;epoll() failed&quot;);            break;        &#125;                // 如果 infds == 0，表示 epoll_wait() 超时        if(infds == 0)        &#123;            printf(&quot;epoll() timeout\n&quot;);            continue;        &#125;                // 如果 infds &gt; 0，表示有事件发生的 socket 的数量        for(int ii = 0; ii &lt; infds; ii++)	// 遍历 epoll 返回的数组 evs        &#123;            // printf(&quot;socket=%d,events=%d\n&quot;, evs[ii].data.fd, evs[ii].events);                        // 如果发生事件的是 listensock，表示已连接队列中有已经准备好的 socket（有新的客户端连上来了）            if(evs[ii].data.fd == listensock)            &#123;                struct sockaddr_in client;                socklen_t len = sizeof(client);                int clientsock = accept(listensock, (struct sockaddr*)&amp;client, &amp;len);                                printf(&quot;accept client(socket=%d) ok\n&quot;, clientsock);                                // 为新客户端准备可读事件，并添加到 epoll 中                ev.data.fd = clientsock;                ev.events = EPOLLIN;                epoll_ctl(epollfd, EPOLL_CTL_ADD, clientsock, &amp;ev);            &#125;else            &#123;                // 如果是客户端连接的 socket 有事件，表示有报文发过来了或者连接已断开                char buffer[1024];			// 存放从客户端读取的数据                memset(buffer, 0, sizeof(buffer));                if(recv(evs[ii].data.fd, buffer, sizeof(buffer), 0) &lt;= 0)                &#123;                    // 如果客户端的连接已断开                    printf(&quot;client(eventfd=%d) disconnected\n&quot;, evs[ii].data.fd);                                        close(evs[ii].data.fd);				// 关闭客户端的 socket                    // 从 epollfd 中删除客户端的 socket，如果 socket 被关闭了，会自动从 epollfd 中删除，所以以下代码不必启用                    // epoll_ctl(epollfd, EPOLL_CTL_DEL, evs[ii].data.fd, 0);                &#125;else                &#123;                    // 如果客户端有报文发过来                    printf(&quot;recv(eventfd=%d):%s\n&quot;, evs[ii].data.fd, buffer);                                        // 把接收到的报文内容原封不动的发回去                    send(evs[ii].data.fd, buffer, strlen(buffer), 0);                &#125;            &#125;        &#125;    &#125;        return 0;&#125;// 初始化服务端的监听端口int initserver(int port)&#123;    int sock = socket(AF_INET, SOCK_STREAM, 0);    if(sock &lt; 0)    &#123;        perror(&quot;socket() failed&quot;);        return -1;    &#125;        int opt = 1;    unsigned int len = sizeof(opt);    setsockopt(sock, SOL_SOCKET, SO_REUSEADDR, &amp;opt, len);        struct sockaddr_in servaddr;    servaddr.sin_family = AF_INET;    servaddr.sin_addr.s_addr = htonl(INADDR_ANY);    servaddr.sin_port = htons(port);        if(bind(sock, (struct sockaddr*)&amp;servaddr, sizeof(servaddr)) &lt; 0)    &#123;        perror(&quot;bind() failed&quot;);        close(sock);        return -1;    &#125;        if(listen(sock, 5) != 0)    &#123;        perror(&quot;listen() failed&quot;);        close(sock);        return -1;    &#125;        return sock;&#125;

/* * 程序名：client.cpp，此程序用于演示采用 epoll 模型实现网络通讯的客户端*/#include &lt;stdio.h&gt;#include &lt;stdlib.h&gt;#include &lt;unistd.h&gt;#include &lt;errno.h&gt;#include &lt;string.h&gt;#include &lt;netinet/in.h&gt;#include &lt;sys/socket.h&gt;#include &lt;arpa/inet.h&gt;int main(int argc, char* argv[])&#123;    if(argc != 3)    &#123;        printf(&quot;usage: ./client ip port\n&quot;);        return -1;    &#125;        int sockfd;    struct sockaddr_in servaddr;    char buf[1024];        if((sockfd = socket(AF_INET, SOCK_STREAM, 0)) &lt; 0)    &#123;        printf(&quot;socket() failed\n&quot;);        return -1;    &#125;        memset(&amp;servaddr, 0, sizeof(servaddr));    servaddr.sin_family = AF_INET;    servaddr.sin_port = htons(atoi(argv[2]));    servaddr.sin_addr.s_addr = inet_addr(argv[1]);        if(connect(sockfd, (struct sockaddr*)&amp;servaddr, sizeof(servaddr)) != 0)    &#123;        printf(&quot;connect(%s:%s) failed\n&quot;, argv[1], argv[2]);        close(sockfd);        return -1;    &#125;        printf(&quot;connect ok\n&quot;);    for(int ii = 0; ii &lt; 1000000; ii++)    &#123;        // 从命令行输入内容        memset(buf, 0, sizeof(buf));        printf(&quot;please input:&quot;);        scanf(&quot;%s&quot;, buf);                if(send(sockfd, buf, strlen(buf), 0) &lt;= 0)        &#123;            printf(&quot;write() failed\n&quot;);            close(sockfd);            return -1;        &#125;                memset(buf, 0, sizeof(buf));        if(recv(sockfd, buf, sizeof(buf), 0) &lt;= 0)        &#123;            printf(&quot;read() failed\n&quot;);            close(sockfd);            return -1;        &#125;                printf(&quot;recv:%s\n&quot;, buf);    &#125;&#125;

