阻塞&amp;非阻塞的 I&#x2F;O
阻塞：在进&#x2F;线程中，发起一个调用时，在调用返回之前，进&#x2F;线程会被阻塞等待，等待中的进&#x2F;线程让出CPU的使用权
非阻塞：在进&#x2F;线程中，发起一个调用时，会立即返回
会阻塞的四个函数：connect()、accept()、send()、recv()
在传统的网络服务端程序中（每连接每线&#x2F;进程），采用阻塞 I&#x2F;O
在 I&#x2F;O 复用的模型中，事件循环不能被阻塞在任何环节，所以应该采用非阻塞 I&#x2F;O

非阻塞 I&#x2F;O - connect()
对非阻塞的 I&#x2F;O 调用 connect() 函数，不管是否能连接成功，connect() 都会立即返回失败，errno &#x3D;&#x3D; EINPROGRESS
对非阻塞的 I&#x2F;O 调用 connect() 函数，如果 socket 的状态是可写的，证明连接是成功的，否则是失败的

/* * 程序名：client1.cpp，网络通讯的客户端程序*/#include &lt;stdio.h&gt;#include &lt;stdlib.h&gt;#include &lt;unistd.h&gt;#include &lt;errno.h&gt;#include &lt;string.h&gt;#include &lt;netinet/in.h&gt;#include &lt;sys/socket.h&gt;#include &lt;arpa/inet.h&gt;#include &lt;poll.h&gt;#include &lt;fcntl.h&gt;// 把 socket 设置成非阻塞int setnonblocking(int fd)&#123;    int flags;        // 获取 fd 的状态    if((flags = fcntl(fd, F_GETFL, 0)) == -1)		flags = 0;        return fcntl(fd, F_SETFL, flags | O_NONBLOCK);&#125;int main(int argc, char* argv[])&#123;    if(argc != 3)    &#123;        printf(&quot;usage: ./client1 ip port\n&quot;);        return -1;    &#125;        int sockfd;    struct sockaddr_in servaddr;    char buf[1024];        if((sockfd = socket(AF_INET, SOCK_STREAM, 0)) &lt; 0)    &#123;        printf(&quot;socket() failed\n&quot;);        return -1;    &#125;        setnonblocking(sockfd);			// 把 sockfd 设置成非阻塞        memset(&amp;servaddr, 0, sizeof(servaddr));    servaddr.sin_family = AF_INET;    servaddr.sin_port = htons(atoi(argv[2]));    servaddr.sin_addr.s_addr = inet_addr(argv[1]);        if(connect(sockfd, (struct sockaddr*)&amp;servaddr, sizeof(servaddr)) != 0)    &#123;        if(errno != EINPROGRESS)        &#123;            printf(&quot;connect(%s:%s) failed\n&quot;, argv[1], argv[2]);        	close(sockfd);        	return -1;        &#125;    &#125;        pollfd fds;    fds.fd = sockfd;    fds.events = POLLOUT;    poll(&amp;fds, 1, -1);    if(fds.revents == POLLOUT)	printf(&quot;connect ok\n&quot;);    else printf(&quot;connect failed\n&quot;);    return 0;&#125;

