非阻塞 I&#x2F;O - accept()
对非阻塞的 I&#x2F;O 调用 accept()，如果已连接队列中没有 socket，函数立即返回失败，errno &#x3D;&#x3D; EAGAIN

非阻塞 I&#x2F;O - recv()
对非阻塞的 I&#x2F;O 调用 recv()，如果没数据可读（接收缓冲区为空），函数立即返回失败，errno &#x3D;&#x3D; EAGAIN

非阻塞 I&#x2F;O - send()
对非阻塞的 I&#x2F;O 调用 send()，如果 socket 不可写（发送缓冲区已满），函数立即返回失败，errno &#x3D;&#x3D; EAGAIN

水平触发&amp;边缘触发
select 和 poll 采用水平触发
epoll 有水平触发和边缘触发两种机制，缺省是水平触发

水平触发
读事件：如果 epoll_wait 触发了读事件，表示有数据可读，如果程序没有把数据读完，再次调用 epoll_wait 的时候，将立即再次触发读事件
写事件：如果发送缓冲区没有满，表示可以写入数据，只要缓冲区没有被写满，再次调用 epoll_wait 的时候，将立即再次触发写事件

边缘触发
读事件：epoll_wait 触发读事件后，不管程序有没有处理读事件，epoll_wait 都不会再触发读事件，只有当新的数据到达时，才再次触发读事件
写事件：epoll_wait 触发写事件之后，如果发送缓冲区仍可以写（发送缓冲区没有满），epoll_wait 不会再次触发写事件，只有当发送缓冲区由满变成不满时，才再次触发写事件
水平触发的代码不能用于边缘触发，但是边缘触发的代码可以用于水平触发

/** 程序名：tcpepoll2.cpp，此程序用于演示采用 epoll 模型的边缘触发*/#include &lt;stdio.h&gt;#include &lt;unistd.h&gt;#include &lt;stdlib.h&gt;#include &lt;string.h&gt;#include &lt;errno.h&gt;#include &lt;sys/socket.h&gt;#include &lt;sys/types.h&gt;#include &lt;arpa/inet.h&gt;#include &lt;sys/fcntl.h&gt;#include &lt;sys/epoll.h&gt;// 把 socket 设置成非阻塞int setnonblocking(int fd)&#123;	int flags;    // 获取 fd 的状态	if((flags = fcntl(fd, F_GETFL, 0)) == -1)	flags = 0;    	return fcntl(fd, F_SETFL, flags | O_NONBLOCK);&#125;// 初始化服务端的监听端口。int initserver(int port);int main(int argc,char* argv[])&#123;    if(argc != 2)     &#123;         printf(&quot;usage: ./tcpepoll2 port\n&quot;);         return -1;     &#125;    	// 初始化服务端用于监听的 socket	int listensock = initserver(atoi(argv[1]));	printf(&quot;listensock=%d\n&quot;, listensock);    	if(listensock &lt; 0)     &#123;         printf(&quot;initserver() failed.\n&quot;);         return -1;     &#125;    	setnonblocking(listensock);		// 把 listensock设置为非阻塞    	// 创建 epoll 句柄	int epollfd = epoll_create(1);    // 为服务端的 listensock 准备读事件	epoll_event ev;			// 声明事件的数据结构	ev.data.fd = listensock;	// 指定事件的自定义数据，会随着 epoll_wait() 返回的事件一并返回	// ev.events = EPOLLIN;		// 打算让 epoll 监视 listensock 的读事件，LT（水平）模式	ev.events = EPOLLIN | EPOLLET;		//打算让 epoll 监视 listensock 的读事件，ET（边缘）模式	    epoll_ctl(epollfd, EPOLL_CTL_ADD, listensock, &amp;ev);	//把需要监视的 socket 和事件加入 epollfd 中    epoll_event evs[10];	// 存放 epoll 返回的事件	    while (true)			// 事件循环	&#123;        // 等待监视的 socket 有事件发生        int infds = epoll_wait(epollfd, evs, 10, -1);                // 返回失败        if(infds &lt; 0)        &#123;        	perror(&quot;epoll() failed&quot;);             break;        &#125;                // 超时        if(infds == 0)        &#123;        	printf(&quot;epoll() timeout\n&quot;);            continue;        &#125;                //如果 infds&gt;0，表示有事件发生的 socket 的数量        for(int ii = 0; ii &lt; infds; ii++)	// 遍历 epoll 返回的数组 evs        &#123;        	// printf(&quot;ptr=%s,events=%d\n&quot;,evs[ii].data.ptr,evs[ii].events);                    	//如果发生事件的是 listensock，表示有新的客户端连上来。        	if (evs[ii].data.fd == listensock)        	&#123;                while (true)                &#123;                    struct sockaddr_in client;                    socklen_t len = sizeof(client);                    int clientsock = accept(listensock, (struct sockaddr*)&amp;client, &amp;len);                    if((clientsock &lt; 0) &amp;&amp; (errno == EAGAIN)) break;	// 如果监听的 socket 是边缘触发的模式，一定要采用非阻塞的 socket，处理事件的时候一定要用循环                                        printf(&quot;accept client(socket=%d) ok.\n&quot;, clientsock);                                        // 为新客户端准备读事件，并添加到 epoll 中                    setnonblocking(clientsock);			// 把客户端连接的 socket 设置为非阻塞                    ev.data.fd = clientsock;                    // ev.events = EPOLLIN;			// LT-水平触发。                    ev.events = EPOLLIN | EPOLLET;		// ET-边缘触发。                    epoll_ctl(epollfd, EPOLL_CTL_ADD, clientsock, &amp;ev);                &#125;        	&#125;            else            &#123;                /*            	printf(&quot; 触发了写件事\n&quot;);                for (int ii = 0; ii &lt; 10000000; ii++)                &#123;                    if(send(ev.data.fd, &quot;aaaaaaaaaaaaaaaaaaaaaaaaaaabbbbbbbbbbbbbb&quot;, 30, 0) &lt;= 0)                    &#123;                        if (errno == EAGAIN)                        &#123;                            printf(&quot;发送缓冲区已填满\n&quot;);                             break;                        &#125;                	&#125;                &#125;                */                // 如果是客户端连接的 socke 有事件，表示有报文发过来或者连接已断开                char buffer[1024];			// 存放从客户端读取的数据                memset(buffer, 0, sizeof(buffer));                int readn;					// 每次调用 recv() 的返回值                char* ptr = buffer;			// buffer 的位置指针                while (true)                &#123;                    if((readn = recv(evs[ii].data.fd, ptr, 5, 0)) &lt;= 0)                    &#123;                        if((readn &lt; 0) &amp;&amp; (errno == EAGAIN))                        &#123;	// 如果数据被读取完了，把接收到的报文内容原封不动的发回去                            send(evs[ii].data.fd, buffer, strlen(buffer), 0);                            printf(&quot;recv(eventfd=%d):%s\n&quot;, evs[ii].data.fd, buffer);                        &#125;                        else                        &#123;                            // 如果客户端的连接已断开                            printf(&quot;client(eventfd=%d) disconnected\n&quot;, evs[ii].data.fd);                            close(evs[ii].data.fd);	// 关闭客户端的 socket                        &#125;                                                break; // 跳出循环。                	&#125;else	ptr = ptr + readn;			// buffer 的位置指针后移                &#125;            &#125;        &#125;    &#125;        return 0;&#125;// 初始化服务端的监听端口int initserver(int port)&#123;    int sock = socket(AF_INET, SOCK_STREAM, 0);    if(sock &lt; 0)    &#123;    	perror(&quot;socket() failed&quot;);        return -1;    &#125;    int opt = 1;     unsigned int len = sizeof(opt);    setsockopt(sock, SOL_SOCKET, SO_REUSEADDR, &amp;opt, len);        struct sockaddr_in servaddr;    servaddr.sin_family = AF_INET;    servaddr.sin_addr.s_addr = htonl(INADDR_ANY);    servaddr.sin_port = htons(port);        if(bind(sock, (struct sockaddr*)&amp;servaddr, sizeof(servaddr)) &lt; 0 )    &#123;    	perror(&quot;bind() failed&quot;);         close(sock);         return -1;    &#125;    if(listen(sock,5) != 0 )    &#123;    	perror(&quot;listen() failed&quot;);         close(sock);         return -1;    &#125;        return sock;&#125;

/** 程序名：client2.cpp，此程序用于演示网络通讯的客户端程序*/#include &lt;stdio.h&gt;#include &lt;stdlib.h&gt;#include &lt;unistd.h&gt;#include &lt;errno.h&gt;#include &lt;string.h&gt;#include &lt;netinet/in.h&gt;#include &lt;sys/socket.h&gt;#include &lt;arpa/inet.h&gt;#include &lt;time.h&gt;int main(int argc, char* argv[])&#123;    if(argc != 3)    &#123;    	printf(&quot;usage:./client2 ip port\n&quot;);         return -1;    &#125;    int sockfd;	struct sockaddr_in servaddr;	char buf[1024];    	if((sockfd = socket(AF_INET, SOCK_STREAM, 0)) &lt; 0)     &#123;         printf(&quot;socket() failed\n&quot;);         return -1;     &#125;        memset(&amp;servaddr, 0, sizeof(servaddr));    servaddr.sin_family = AF_INET;    servaddr.sin_port = htons(atoi(argv[2]));    servaddr.sin_addr.s_addr = inet_addr(argv[1]);        if(connect(sockfd, (struct sockaddr*)&amp;servaddr, sizeof(servaddr)) != 0)    &#123;        printf(&quot;connect(%s:%s) failed\n&quot;, argv[1], argv[2]);         close(sockfd);        return -1;    &#125;        printf(&quot;connect ok\n&quot;);	// printf(&quot;开始时间：%d&quot;, time(0));        for(int ii = 0; ii &lt; 200000; ii++)    &#123;    	//从命令行输入内容。        memset(buf,0,sizeof(buf));        printf(&quot;please input:&quot;); scanf(&quot;%s&quot;,buf);            	//strcpy(buf,&quot;aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaabbbbbbbbbbbbbbccccccccccccccccddddddddddddd&quot;);            if(send(sockfd, buf, strlen(buf), 0) &lt;= 0)        &#123;            printf(&quot;write() failed\n&quot;);            close(sockfd);            return -1;        &#125;            	memset(buf,0,sizeof(buf));    	if(recv(sockfd, buf, sizeof(buf), 0) &lt;= 0)        &#123;            printf(&quot;read() failed\n&quot;);            close(sockfd);            return -1;        &#125;    	printf(&quot;recv:%s\n&quot;,buf);    &#125;    	// printf(&quot;结束时间：%d&quot;, time(0));&#125;

// 终端// 服务端[zxc@study CppNetworkProgramming]$ g++ -std=c++11 -g -o tcpepoll2 tcpepoll2.cpp[zxc@study CppNetworkProgramming]$ ./tcpepoll2 5008listensock=3accept client(socket=5) ok.recv(eventfd=5):aaaaaaaaaaaccept client(socket=6) ok.recv(eventfd=6):bbbbbbbbbbclient(eventfd=6) disconnectedclient(eventfd=5) disconnected^C// 1号客户端[zxc@study CppNetworkProgramming]$ g++ -std=c++11 -g -o client2 client2.cpp[zxc@study CppNetworkProgramming]$ ./client2 192.168.112.132 5008connect okplease input:aaaaaaaaaarecv:aaaaaaaaaaplease input:^C// 2号客户端[zxc@study CppNetworkProgramming]$ ./client2 192.168.112.132 5008connect okplease input:bbbbbbbbbbrecv:bbbbbbbbbbplease input:^C

