使用容器 vector每次存满后扩充当前空间倍数（2倍或者其他）每次扩充两倍或者其他倍数
#include &lt;vector&gt;#include &lt;stdexcept&gt;#include &lt;string&gt;#include &lt;cstdlib&gt;	// abort()#include &lt;cstdio&gt;	// snprintf()#include &lt;iostream&gt;#include &lt;ctime&gt;#include &lt;algorithm&gt;	// sort(), find()namespace star02&#123;    void test_vector(long&amp; value)    &#123;        cout &lt;&lt; &quot;\ntest_vector().......... \n&quot;;            vector&lt;string&gt; c;    char buf[10];            clock_t timeStart = clock();        for(long i=0; i&lt; value; ++i)        &#123;            try &#123;                snprintf(buf, 10, &quot;%d&quot;, rand());                c.push_back(string(buf));            &#125;            catch(exception&amp; p) &#123;	// 捕获异常，防止分配空间失败                cout &lt;&lt; &quot;i=&quot; &lt;&lt; i &lt;&lt; &quot; &quot; &lt;&lt; p.what() &lt;&lt; endl;                	// 曾经最高 i=58389486 then std::bad_alloc                abort();            &#125;        &#125;        cout &lt;&lt; &quot;mulli-seconds : &quot; &lt;&lt; (clock()-timeStart) &lt;&lt; endl;        cout &lt;&lt; &quot;vector.size()= &quot; &lt;&lt; c.size() &lt;&lt; endl;	// vector中实际元素个数        cout &lt;&lt; &quot;vecotr.front()= &quot; &lt;&lt; c.front() &lt;&lt; endl;        cout &lt;&lt; &quot;vector.back()= &quot; &lt;&lt; c.back() &lt;&lt; endl;        cout &lt;&lt; &quot;vector.data()= &quot; &lt;&lt; c.data() &lt;&lt; endl;	// vector空间的首地址        cout &lt;&lt; &quot;vector.capacity()= &quot; &lt;&lt; c.capacity() &lt;&lt; endl;	// vector申请的空间数量，只能往后扩大，且成倍扩大，当空间满时，申请一个当前空间两倍（可能其他倍数）的空间，将原来的数据一个个复制到新空间，然后删除原空间                    string target = get_a_target_string();        &#123;            timeStart = clock();        auto pItem = ::find(c.begin(), c.end(), target);	// 函数名字前面加::表示为全局函数，如果没有写，编译器在当前作用域没有找到该函数，也会到全局去找，加::更明白些            cout &lt;&lt; &quot;::find(), milli-seconds : &quot; &lt;&lt; (clock()-timeStart) &lt;&lt; endl;                        if (pItem != c.end())                cout &lt;&lt; &quot;found, &quot; &lt;&lt; *pItem &