void push_back(const T&amp; x) &#123;    if (finish != end_of_storage) &#123;	// 尚有备用空间        construct(finish, x);		// 全局函数        ++finish;					// 调整水位高度    &#125;    else	// 已无备用空间        insert_aux(end(), x);&#125;template &lt;class T, class Alloc&gt;void vector&lt;T,Alloc&gt;::insert_aux(iterator position, const T&amp; x) &#123;    if (finish != end_of_storage) &#123;	// 尚有备用空间，insert_aux() 除了被 push_back 调用之外还会被其他函数调用，所以检查        // 在备用空间起始处建构一个元素，并以 vector 最后一个元素值为其初值        construct(finish, *(finish - 1));        ++finish;	// 调整水位        T x_copy = x;        copy_backward(position, finish - 2, finish - 1);        *position = x_copy;    &#125;    else &#123;	// 已无备用空间        const size_type old_size = size();        const size_type len = old_size != 0 ? 2 * old_size : 1;        // 以上分配原则：如果原大小为0，则分配1（个元素大小）        // 如果原大小不为0，则分配原大小的两倍        // 前半段用来放置原数据，后半段准备用来放置新数据                iterator new_start = data_allocator::allocate(len);        iterator new_finish = new_start;        try &#123;            // 将原 vector 的内容拷贝到新 vector            new_finish = uninitialized_copy(start, position, new_start);            construct(new_finish, x);	// 为新元素设初值 x            ++new_finish;	// 调整水位            // 拷贝安插点后的原内容（因它也可能被 insert(p,x) 呼叫）            new_finish = uninitialized_copy(position, finish, new_finish);        &#125;        catch(...) &#123;            // &quot;commit or rollback&quot; semantics            destroy(new_start, new_finish);            data_allocator::deallocate(new_start, len);            throw;        &#125;        // 解构并释放原 vector        destroy(begin(), end());        deallocate();        // 调整迭代器，指向新 vector        start = new_start;        finish = new_finish;        end_of_storage = new_start + len;    &#125;&#125;

