template &lt;class T, class Alloc=alloc, size_t BufSiz=0&gt; // BufSiz 所谓 buffer size 是指每个 buffer 容纳的元素个数class deque &#123;    public:    	typedef T value_type;    	typedef __deque_iterator&lt;T,T&amp;,T*,BufSiz&gt; iterator;    protected:    	typedef pointer* map_pointer;	// T**    protected:    	iterator start;			// sizeof(vector&lt;T&gt;) = 40    	iterator finish;		// sizeof(iterator) = 16    	map_pointer map;    	size_type map_size;    public:    	iterator begin() &#123; return start; &#125;    	iterator end() &#123; return finish; &#125;    	size_type size() const &#123; return finish - start; &#125;    ...&#125;;// 如果 n 不为 0，返回 n，表示 buffer size 由使用者自定// 如果 n 为 0，表示 buffer size 使用预设值，那么//	如果 sz（sizeof(value_type)）小于512，返回 512/sz//	如果 sz 不小于512，返回1inline size_t __deque_buf_size(size_t n, size_t sz)&#123;    return n != 0 ? n : (sz &lt; 512 ? size_t(512 / sz) : size_t(1));&#125;

deque’iteratortemplate &lt;class T, class Ref, class Ptr, size_t BufSiz&gt;struct __deque_iterator &#123;    typedef random_access_iterator_tag iterator_category;	// (1)    typedef T value_type;								// (2)    typedef Ptr pointer;								// (3)    typedef Ref reference;								// (4)    typedef size_t size_type;    typedef ptrdiff_t difference_type;					// (5)    typedef T** map_pointer;    typedef __deque_iterator self;        T* cur;    T* first;    T* last;    map_pointer node;    ...&#125;;

deque&lt;T&gt;::insert()// 在 position 处安插一个元素，其值为 xiterator insert(iterator position, const value_type&amp; x) &#123;    if (postion.cur == start.cur) &#123;	// 如果安插点是 deque 最前端        push_front(x);				// 交给 push_front() 做        return start;    &#125;    else if (position.cur == finish.cur) &#123;	// 如果安插点是 deque 最尾端        push_back(x);						// 交给 push_back() 做        iterator tmp = finish;        --tmp;        return tmp;    &#125;    else &#123;        return insert_aux(position, x);    &#125;&#125;template &lt;class T, class Alloc, size_t BufSize&gt;typename deque&lt;T, Alloc, BufSize&gt;::iteratordeque&lt;T, Alloc, BufSize&gt;::insert_aux(iterator pos, const value_type&amp; x) &#123;    difference_type index = pos - start;	// 安插点之前的元素个数    value_type x_copy = x;    if (index &lt; size() / 2) &#123;			// 如果安插点之前的元素个数较少        push_front(front());			// 在最前端加入与第一元素同值的元素        ...        copy(front2, pos1, front1);		// 元素搬移    &#125;    else &#123;						// 安插点之后的元素个数较少        push_back(back());		// 在尾端加入与最末元素同值的元素        ...        copy_backward(pos, back2, back1);	// 元素搬移    &#125;    *pos = x_copy;	// 在安插点上设定新值    return pos;&#125;

deque 如何模拟连续空间全都是 deque iterators 的功劳
reference operator[](size_type n)&#123;    return start[difference_type(n)];&#125;reference front()&#123;    return *start;&#125;reference back()&#123;    iterator tmp = finish;    --tmp;    return *tmp;&#125;size_type size() const&#123;    return finish - start;&#125;bool empty() const&#123;    return finish == start;&#125;reference operator*() const&#123;    return *cur;&#125;pointer operator-&gt;() const&#123;    return &amp;(operator*());&#125;// 两根 iterators 之间的距离相当于// (1) 两根 iterators 间的 buffers 的总长度 +// (2) itr 至其 buffer 末尾的长度 +// (3) x 至其 buffer 起头的长度difference_type operator-(const self&amp; x) const&#123;    return difference_type(buffer_size()) * (node - x.node - 1) + (cur - first) + (x.last - x.cur);    // node - x.node - 1 首尾 buffers 之间的 buffers 数量    // cur - first 末尾(当前) buffer 的元素量    // x.last - x.cur 起始 buffer 的元素量&#125;void set_node(map_pointer new_node) &#123;    node = new_node;    first = *new_node;    last = first + difference_type(buffer_size());&#125;self&amp; operator++() &#123;    ++cur;					// 切换至下一元素    if (cur == last) &#123;			// 如果抵达缓冲区尾端        set_node(node + 1);		// 就跳至下一节点（缓冲区）        cur = first;			// 的起点    &#125;    return *this;&#125;self operator++(int) &#123;    self tmp = *this;    ++*this;    return tmp;&#125;self&amp; operator--() &#123;    if (cur == first) &#123;			// 如果目前在缓冲区起头        set_node(node - 1);		// 就跳至前一节点（缓冲区）        cur = last;				// 的最末端    &#125;    --cur;						// 往前移一元素（此即最末元素）    return *this;&#125;self operator--(int) &#123;    self tmp = *this;    --*this;    return tmp;&#125;self&amp; operator+=(difference_type n) &#123;    difference_type offset = n + (cur - first);    if (offset &gt;= 0 &amp;&amp; offset &lt; difference_type(buffer_size()))        // 目标位置在同一缓冲区内        cur += n;    else &#123;        // 目标位置不在同一缓冲区内        difference_type node_offset = offset &gt; 0 ? offset / difference_type(buffer_size())            									: -difference_type((-offset - 1) / buffer_size()) - 1;        // 切换至正确的缓冲区        set_node(node + node_offset);        // 切换至正确的元素        cur = first + (offset - node_offset * difference_type(buffer_size()));    &#125;    return *this;&#125;self operator+(difference_type n) const &#123;    self tmp = *this;    return tmp += n;&#125;self&amp; operator-=(difference_type n) &#123;     return *this += -n;&#125;self operator-(difference_type n) const &#123;	self tmp = *this;    return tmp -= n;&#125;reference operator[](difference_type n) const &#123;    return *(*this + n);&#125;

