迭代器分类（category）对算法的影响iterator_category 对算法的影响// 由于继承关系，没有专属设计的版本，会调用继承的版本，如 forward_iterator_tag 和 bidirectional_iterator_tag 会调用此版本template &lt;class InputIterator&gt;inline iterator_traits&lt;InputIterator&gt;::difference_type     __distance(InputIterator first, InputIterator last, input_iterator_tag) &#123;	    iterator_traits&lt;InputIterator&gt;::difference_type n = 0;    while(first != last) &#123;        ++first;        ++n;    &#125;    return n;&#125;template &lt;class RandomAccessIterator&gt;inline iterator_traits&lt;RandomAccessIterator&gt;::difference_type    __distance(RandomAccessIterator first, RandomAccessIterator last, random_access_iterator_tag) &#123;    return last - first;&#125;template &lt;class InputIterator&gt;inline iterator_traits&lt;InputIterator&gt;::difference_type    distance(InputIterator first, InputIterator last) &#123;	// 两个指针的距离，主函数根据迭代器的分类调用次函数    typedef typename iterator_traits&lt;InputIterator&gt;::iterator_category category;    return __distance(first, last, category());	// category() temp. obj&#125;

template &lt;class InputIterator, class Distance&gt;inline void __advance(InputIterator&amp; i, Distance n, input_iterator_tag) &#123;    while(n--) ++i;&#125;template &lt;class BidirectionalIterator, class Distance&gt;inline void __advance(BidirectionalIterator&amp; i, Distance n, bidirectional_iterator_tag) &#123;    if(n&gt;=0)        while(n--) ++i;    else        while(n++) --i;&#125;template &lt;class RandomAccessIterator, class Distance&gt;inline void __advance(RandomAccessIterator&amp; i, Distance n, random_access_iterator_tag) &#123;    i += n;&#125;template &lt;class InputIterator, class Distance&gt;inline void advance(InputIterator&amp; i, Distance n) &#123;	// 指针前进 n 步    __advance(i, n, iterator_category(i));&#125;template &lt;class Iterator&gt;inline typename iterator_traits&lt;Iterator&gt;::iterator_category iterator_category(const Iterator&amp;) &#123;    typedef typename iterator_traits&lt;Iterator&gt;::iterator_category category;    return category();	// 此函数协助取出 iterator 的 category 并以此创建一个 temp. object&#125;

