算法 replace, replace_if, replace_copytemplate &lt;class ForwardIterator, class T&gt;void replace(ForwardIterator first, ForwardIterator last, const T&amp; old_value, const T&amp; new_value) &#123;    // 范围内所有等同于 old_value 者都以 new_value 取代    for ( ; first != last; ++first)        if (*first == old_value)            *first = new_value;&#125;

