template &lt;class InputIterator, class OutputIterator, class T&gt;OutputIterator replace_copy(InputIterator first,                             InputIterator last,                             OutputIterator result,                             const T&amp; old_value,                             const T&amp; new_value) &#123;    // 范围内所有等同于 old_value 者都以 new_value 放至新区间，不符合者原值放入新区间    for ( ; first != last; ++first, ++result)        *result = *first==old_value ? new_value : *first;    return result;&#125;

