template &lt;class ForwardIterator, class T&gt;bool binary_search(ForwardIterator first, ForwardIterator last, const T&amp; val)&#123;    first = std::lower_bound(first, last, val);    return (first!=last &amp;&amp; !(val &lt; *first));	// 获得的 iterator 所指的位置既非 end，目标值 val 亦不小于首元素（sorted range 之首元素值最小）&#125;// 优化：先判断 !(val &lt; *first) 然后才调用 lower_bound() 将获得较佳效率。因为进入 lower_bound() 后乃由中间元素开始比较，虽说二分搜寻也快，毕竟都不必要了// Returns an iterator pointing to the first element in the range [first,last) which does not compare less than val// The elements are compared using operator&lt; for the first version, and comp for the second// The elements in the range shall already be sorted according to this same criterion(operator&lt; or comp), or at least partitioned with respect to valtemplate &lt;class ForwardIterator, class T&gt;ForwardIterator lower_bound(ForwardIterator first, ForwardIterator last, const T&amp; val)&#123;    ForwardIterator it;    iterator_traits&lt;ForwardIterator&gt;::difference_type count, step;    count = distance(first, last);    while(count&gt;0)	// 二分查找    &#123;        it = first;        step = count/2;        advance(it,step);        if(*it&lt;val) &#123;	// or: if(comp(*it, val)), for version(2)            first = ++ it;            count -= step+1;        &#125;        else count=step;    &#125;    return first;&#125;

