// 辅助函数，让 user 得以方便使用 binder2nd&lt;Op&gt;// 编译器会自带推导 Op 的 typetemplate &lt;class Operation, class T&gt;inline binder2nd&lt;Operation&gt; bind2nd(const Operation&amp; op, const T&amp; x) &#123;    // typename 帮助编译器通过代码，编译器编译到这里还不知道 Operation，Operation 要到传参数进来进行实参推导才知道，正常编译到这里会失败    typedef typename Operation::second_argument_type arg2_type;	// 问 Operation 第二实参是什么类型    return binder2nd&lt;Operation&gt;(op, arg2_type(x));	// 看 x 是不是这个类型或者能不能转换为这个类型&#125;// 类模板没有类型自动推导，靠函数模板推导后传给类模板// 以下将某个 Adaptable Binary function 转换为 Unary Functiontemplate &lt;class Operation&gt;	// 如果还要再被 adapter 的话也要回答参数和返回类型，所以要继承 unary_function()class binder2nd : public unary_function&lt;typename Operation::first_argument_type, typename Operation::result_type&gt; &#123;    protected:    	Operation op;	// 内部成员，分别用以记录算式和第二实参    	typename Operation::second_argument_type value;    public:    	// constructor，将算式和第二实参记录下来    	binder2nd(const Operation&amp; x, const typename Operation::second_argument_type&amp; y) : op(x), value(y) &#123;&#125;    	typename Operation::result_type operator()(const typename Operation::first_argument_type&amp; x) const &#123;            return op(x, value);	// 实际呼叫算式并取 value 为第二实参        &#125;&#125;;template &lt;class InputIterator, class Predicate&gt;typename iterator_traits&lt;InputIterator&gt;::difference_type     count_if(InputIterator first, InputIterator last, Predicate pred) &#123;    // 以下定义一个初值为0的计数器    typename iterator_traits&lt;InputIterator&gt;::difference_type n = 0;    for ( ; first != last; ++first)	// 遍历        if(pred(*first))	// 如果元素带入 pred 的结果为 true            ++n;			// 计数器累加1    return n;&#125;

